NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'I Samuel'

CHAPTERS = {
    1: {
        1: 'Fuit vir unus de Ramathaimsophim, de monte Ephraim, et nomen eius Elcana, filius Ieroham, filii Eliu, filii Thohu, filii Suph, Ephrathaeus:',
        2: 'et habuit duas uxores, nomen uni Anna, et nomen secundae Phenenna. Fueruntque Phenennae filii: Annae autem non erant liberi.',
        3: 'Et ascendebat vir ille de civitate sua statutis diebus, ut adoraret et sacrificaret Domino exercituum in Silo. Erant autem ibi duo filii Heli, Ophni et Phinees, sacerdotes Domini.',
        4: 'Venit ergo dies, et immolavit Elcana, deditque Phenennae uxori suae, et cunctis filiis eius, et filiabus partes:',
        5: 'Annae autem dedit partem unam tristis, quia Annam diligebat. Dominus autem concluserat vulvam eius.',
        6: 'Affligebat quoque eam aemula eius, et vehementer angebat, in tantum, ut exprobraret quod Dominus conclusisset vulvam eius:',
        7: 'sicque faciebat per singulos annos, cum redeunte tempore ascenderent ad templum Domini: et sic provocabat eam. porro illa flebat, et non capiebat cibum.',
        8: 'Dixit ergo ei Elcana vir suus: Anna, cur fles? et quare non comedis? et quam ob rem affligitur cor tuum? numquid non ego melior tibi sum, quam decem filii?',
        9: 'Surrexit autem Anna postquam comederat, et biberat in Silo. Et Heli sacerdote sedente super Sellam ante postes domus Domini,',
        10: 'cum esset Anna amaro animo, oravit ad Dominum, flens largiter,',
        11: 'et votum vovit, dicens: Domine exercituum, si respiciens videris afflictionem famulae tuae, et recordatus mei fueris, nec oblitus ancillae tuae, dederisque servae tuae sexum virilem: dabo eum Domino omnibus diebus vitae eius, et novacula non ascendet super caput eius.',
        12: 'Factum est autem, cum illa multiplicaret preces coram Domino, ut Heli observaret os eius.',
        13: 'Porro Anna loquebatur in corde suo, tantumque labia illius movebantur, et vox penitus non audiebatur. Aestimavit ergo eam Heli temulentam,',
        14: 'dixitque ei: Usquequo ebria eris? digere paulisper vinum, quo mades.',
        15: 'Respondens Anna, Nequaquam, inquit, domine mi: nam mulier infelix nimis ego sum, vinumque et omne quod inebriare potest, non bibi, sed effudi animam meam in conspectu Domini.',
        16: 'Ne reputes ancillam tuam quasi unam de filiabus Belial: quia ex multitudine doloris, et moeroris mei locuta sum usque in praesens.',
        17: 'Tunc Heli ait ei: Vade in pace: et Deus Israel det tibi petitionem tuam, quam rogasti eum.',
        18: 'Et illa dixit: Utinam inveniat ancilla tua gratiam in oculis tuis. Et abiit mulier in viam suam, et comedit, vultusque illius non sunt amplius in diversa mutati.',
        19: 'Et surrexerunt mane, et adoraverunt coram Domino: reversique sunt, et venerunt in domum suam in Ramatha. Cognovit autem Elcana Annam uxorem suam: et recordatus est eius Dominus.',
        20: 'Et factum est post circulum dierum, concepit Anna, et peperit filium, vocavitque nomen eius Samuel: eo quod a Domino postulasset eum.',
        21: 'Ascendit autem vir eius Elcana, et omnis domus eius, ut immolaret Domino hostiam sollemnem, et votum suum,',
        22: 'et Anna non ascendit: dixit enim viro suo: Non vadam, donec ablactetur infans, et ducam eum, ut appareat ante conspectum Domini, et maneat ibi iugiter.',
        23: 'Et ait ei Elcana vir suus: Fac quod bonum tibi videtur, et mane donec ablactes eum: precorque ut impleat Dominus verbum suum. Mansit ergo mulier, et lactavit filium suum, donec amoveret eum a lacte.',
        24: 'Et adduxit eum secum, postquam ablactaverat, in vitulis tribus, et tribus modiis farinae, et amphora vini, et adduxit eum ad domum Domini in Silo. Puer autem erat adhuc infantulus:',
        25: 'et immolaverunt vitulum, et obtulerunt puerum Heli.',
        26: 'Et ait Anna: Obsecro mi domine, vivit anima tua domine: ego sum illa mulier, quae steti coram te hic orans Dominum.',
        27: 'Pro puero isto oravi, et dedit mihi Dominus petitionem meam, quam postulavi eum.',
        28: 'Idcirco et ego commodavi eum Domino cunctis diebus, quibus fuerit commodatus Domino. Et adoraverunt ibi Dominum. Et oravit Anna, et ait:',
    },
    2: {
        1: 'Exultavit cor meum in Domino, et exaltatum est cornu meum in Deo meo: dilatatum est os meum super inimicos meos: quia laetata sum in salutari tuo.',
        2: 'Non est sanctus, ut est Dominus: neque enim est alius extra te, et non est fortis sicut Deus noster.',
        3: 'Nolite multiplicare loqui sublimia, gloriantes: recedant vetera de ore vestro: quia Deus scientiarum, Dominus est, et ipsi praeparantur cogitationes.',
        4: 'Arcus fortium superatus est, et infirmi accincti sunt robore.',
        5: 'Repleti prius, pro panibus se locaverunt: et famelici saturati sunt, donec sterilis peperit plurimos: et quae multos habebat filios, infirmata est.',
        6: 'Dominus mortificat et vivificat, deducit ad inferos et reducit.',
        7: 'Dominus pauperem facit et ditat, humiliat et sublevat.',
        8: 'Suscitat de pulvere egenum, et de stercore elevat pauperem: ut sedeat cum principibus, et solium gloriae teneat. Domini enim sunt cardines terrae, et posuit super eos orbem.',
        9: 'Pedes sanctorum suorum servabit, et impii in tenebris conticescent: quia non in fortitudine sua roborabitur vir.',
        10: 'Dominum formidabunt adversarii eius: et super ipsos in caelis tonabit: Dominus iudicabit fines Terrae, et dabit imperium regi suo, et sublimabit cornu Christi sui.',
        11: 'Et abiit Elcana in Ramatha, in domum suam: puer autem erat minister in conspectu Domini ante faciem Heli sacerdotis.',
        12: 'Porro filii Heli, filii Belial, nescientes Dominum,',
        13: 'neque officium sacerdotum ad populum: sed quicumque immolasset victimam, veniebat puer sacerdotis, dum coquerentur carnes, et habebat fuscinulam tridentem in manu sua,',
        14: 'et mittebat eam in lebetem, vel in caldariam, aut in ollam, sive in cacabum: et omne, quod levabat fuscinula, tollebat sacerdos sibi. sic faciebant universo Israeli venientium in Silo.',
        15: 'Etiam antequam adolerent adipem, veniebat puer sacerdotis, et dicebat immolanti: Da mihi carnem, ut coquam sacerdoti: non enim accipiam a te carnem coctam, sed crudam.',
        16: 'Dicebatque illi immolans: Incendatur primum iuxta morem hodie adeps, et tolle tibi quantumcumque desiderat anima tua. Qui respondens aiebat ei: Nequaquam: nunc enim dabis, alioquin tollam vi.',
        17: 'Erat ergo peccatum puerorum grande nimis coram Domino: quia retrahebant homines a sacrificio Domini.',
        18: 'Samuel autem ministrabat ante faciem Domini, puer accinctus ephod lineo.',
        19: 'Et tunicam parvam faciebat ei mater sua, quam afferebat statutis diebus, ascendens cum viro suo, ut immolaret hostiam sollemnem.',
        20: 'Et benedixit Heli Elcanae et uxori eius: dixitque ei: Reddat tibi Dominus semen de muliere hac, pro foenore quod commodasti Domino. Et abierunt in locum suum.',
        21: 'Visitavit ergo Dominus Annam, et concepit, et peperit tres filios, et duas filias: et magnificatus est puer Samuel apud Dominum.',
        22: 'Heli autem erat senex valde, et audivit omnia quae faciebant filii sui universo Israeli: et quomodo dormiebant cum mulieribus quae observabant ad ostium tabernaculi:',
        23: 'et dixit eis: Quare facitis res huiuscemodi, quas ego audio, res pessimas, ab omni populo?',
        24: 'Nolite filii mei: non enim est bona fama, quam ego audio, ut transgredi faciatis populum Domini.',
        25: 'Si peccaverit vir in virum, placari ei potest Deus: si autem in Dominum peccaverit vir, quis orabit pro eo? Et non audierunt vocem patris sui: quia voluit Dominus occidere eos.',
        26: 'Puer autem Samuel proficiebat, atque crescebat, et placebat tam Deo quam hominibus.',
        27: 'Venit autem vir Dei ad Heli, et ait ad eum: Haec dicit Dominus: Numquid non aperte revelatus sum domui patris tui, cum essent in Aegypto in domo Pharaonis?',
        28: 'Et elegi eum ex omnibus tribubus Israel mihi in sacerdotem, ut ascenderet ad altare meum, et adoleret mihi incensum, et portaret ephod coram me: et dedi domui patris tui omnia de sacrificiis filiorum Israel.',
        29: 'Quare calce abiecistis victimam meam, et munera mea quae praecepi ut offerrentur in templo: et magis honorasti filios tuos quam me, ut comederetis primitias omnis sacrificii Israel populi mei?',
        30: 'Propterea ait Dominus Deus Israel: Loquens locutus sum, ut domus tua, et domus patris tui ministraret in conspectu meo, usque in sempiternum. Nunc autem dicit Dominus: Absit hoc a me: sed quicumque honorificaverit me, glorificabo eum: qui autem contemnunt me, erunt ignobiles.',
        31: 'Ecce dies veniunt: et praecidam brachium tuum, et brachium domus patris tui, ut non sit senex in domo tua.',
        32: 'Et videbis aemulum tuum in templo, in universis prosperis Israel: et non erit senex in domo tua omnibus diebus.',
        33: 'Verumtamen non auferam penitus virum ex te ab altari meo: sed ut deficiant oculi tui, et tabescat anima tua: et pars magna domus tuae morietur cum ad virilem aetatem venerit.',
        34: 'Hoc autem erit tibi signum, quod venturum est duobus filiis tuis, Ophni et Phinees: In die uno morientur ambo.',
        35: 'Et suscitabo mihi sacerdotem fidelem, qui iuxta cor meum, et animam meam faciet: et aedificabo ei domum fidelem, et ambulabit coram Christo meo cunctis diebus.',
        36: 'Futurum est autem, ut quicumque remanserit in domo tua, veniat ut oretur pro eo, et offerat nummum argenteum, et tortam panis, dicatque: Dimitte me obsecro ad unam partem sacerdotalem, ut comedam buccellam panis.',
    },
    3: {
        1: 'Puer autem Samuel ministrabat Domino coram Heli, et sermo Domini erat pretiosus in diebus illis, non erat visio manifesta.',
        2: 'Factum est ergo in die quadam, Heli iacebat in loco suo, et oculi eius caligaverant, nec poterat videre:',
        3: 'lucernam Dei antequam extingueretur, Samuel autem dormiebat in templo Domini, ubi erat arca Dei.',
        4: 'Et vocavit Dominus Samuel. Qui respondens, ait: Ecce ego.',
        5: 'Et cucurrit ad Heli, et dixit: Ecce ego: vocasti enim me. Qui dixit: Non vocavi: revertere, et dormi. Et abiit, et dormivit.',
        6: 'Et adiecit Dominus rursum vocare Samuelem. Consurgensque Samuel, abiit ad Heli, et dixit: Ecce ego: quia vocasti me. Qui respondit: Non vocavi te fili mi: revertere et dormi.',
        7: 'Porro Samuel necdum sciebat Dominum, neque revelatus fuerat ei sermo Domini.',
        8: 'Et adiecit Dominus, et vocavit adhuc Samuelem tertio. Qui consurgens abiit ad Heli,',
        9: 'et ait: Ecce ego: quia vocasti me. Intellexit ergo Heli quia Dominus vocaret puerum: et ait ad Samuelem: Vade, et dormi: et si deinceps vocaverit te, dices: Loquere Domine, quia audit servus tuus. Abiit ergo Samuel, et dormivit in loco suo.',
        10: 'Et venit Dominus, et stetit: et vocavit, sicut vocaverat secundo, Samuel, Samuel. Et ait Samuel: Loquere Domine, quia audit servus tuus.',
        11: 'Et dixit Dominus ad Samuelem: Ecce ego facio verbum in Israel: quod quicumque audierit, tinnient ambae aures eius.',
        12: 'In die illa suscitabo adversum Heli omnia quae locutus sum super domum eius: incipiam, et complebo.',
        13: 'Praedixi enim ei quod iudicaturus essem domum eius in aeternum, propter iniquitatem, eo quod noverat indigne agere filios suos, et non corripuerit eos.',
        14: 'Idcirco iuravi Domui Heli quod non expietur iniquitas domus eius victimis et muneribus usque in aeternum.',
        15: 'Dormivit autem Samuel usque mane, aperuitque ostia domus Domini. Et Samuel timebat indicare visionem Heli.',
        16: 'Vocavit ergo Heli Samuelem, et dixit: Samuel fili mi? Qui respondens, ait: Praesto sum.',
        17: 'Et interrogavit eum: Quis est sermo, quem locutus est Dominus ad te? oro te ne celaveris me. haec faciat tibi Deus, et haec addat, si absconderis a me sermonem ex omnibus verbis, quae dicta sunt tibi.',
        18: 'Indicavit itaque ei Samuel universos sermones, et non abscondit ab eo. Et ille respondit: Dominus est: quod bonum est in oculis suis faciat.',
        19: 'Crevit autem Samuel, et Dominus erat cum eo, et non cecidit ex omnibus verbis eius in terram.',
        20: 'Et cognovit universus Israel a Dan, usque Bersabee, quod fidelis Samuel propheta esset Domini.',
        21: 'Et addidit Dominus ut appareret in Silo, quoniam revelatus fuerat Dominus Samueli in Silo, iuxta verbum Domini. Et evenit sermo Samuelis universo Israeli.',
    },
    4: {
        1: 'Et factum est in diebus illis, convenerunt Philisthiim in pugnam: egressus est namque Israel obviam Philisthiim in praelium, et castrametatus est iuxta Lapidem adiutorii. Porro Philisthiim venerunt in Aphec,',
        2: 'et instruxerunt aciem contra Israel. Inito autem certamine, terga vertit Israel Philisthaeis: et caesa sunt in illo certamine passim per agros, quasi quattuor millia virorum.',
        3: 'Et reversus est populus ad castra: dixeruntque maiores natu de Israel: Quare percussit nos Dominus hodie coram Philisthiim? Afferamus ad nos de Silo arcam foederis Domini, et veniat in medium nostri, ut salvet nos de manu inimicorum nostrorum.',
        4: 'Misit ergo populus in Silo, et tulerunt inde arcam foederis Domini exercituum sedentis super Cherubim: erantque duo filii Heli cum arca foederis Domini, Ophni et Phinees.',
        5: 'Cumque venisset arca foederis Domini in castra, vociferatus est omnis Israel clamore grandi, et personuit terra.',
        6: 'Et audierunt Philisthiim vocem clamoris, dixeruntque: Quaenam est haec vox clamoris magni in castris Hebraeorum? Et cognoverunt quod arca Domini venisset in castra.',
        7: 'Timueruntque Philisthiim, dicentes: Venit Deus in castra. Et ingemuerunt, dicentes:',
        8: 'Vae nobis: non enim fuit tanta exultatio heri et nudiustertius: vae nobis. Quis nos salvabit de manu Deorum sublimium istorum? hi sunt Dii, qui percusserunt Aegyptum omni plaga, in deserto.',
        9: 'Confortamini, et estote viri, Philisthiim: ne serviatis Hebraeis, sicut et illi servierunt nobis: confortamini, et bellate.',
        10: 'Pugnaverunt ergo Philisthiim, et caesus est Israel, et fugit unusquisque in tabernaculum suum: et facta est plaga magna nimis: et ceciderunt de Israel triginta millia peditum.',
        11: 'Et arca Dei capta est: duo quoque filii Heli mortui sunt, Ophni et Phinees.',
        12: 'Currens autem vir de Beniamin ex acie, venit in Silo in die illa, scissa veste, et conspersus pulvere caput.',
        13: 'Cumque ille venisset, Heli sedebat super sellam contra viam spectans. Erat enim cor eius pavens pro arca Dei. Vir autem ille postquam ingressus est, nunciavit urbi: et ululavit omnis civitas.',
        14: 'Et audivit Heli sonitum clamoris, dixitque: Quis est hic sonitus tumultus huius? At ille festinavit, et venit, et nunciavit Heli.',
        15: 'Heli autem erat nonaginta et octo annorum, et oculi eius caligaverant, et videre non poterat.',
        16: 'Et dixit ad Heli: Ego sum qui veni de praelio, et ego qui de acie fugi hodie. Cui ille ait: Quid actum est fili mi?',
        17: 'Respondens autem ille, qui nunciabat, Fugit, inquit, Israel coram Philisthiim, et ruina magna facta est in populo: insuper et duo filii tui mortui sunt, Ophni et Phinees: et arca Dei capta est.',
        18: 'Cumque ille nominasset arcam Dei, cecidit de sella retrorsum iuxta ostium, et fractis cervicibus mortuus est. Senex enim erat vir et grandaevus: et ipse iudicavit Israel quadraginta annis.',
        19: 'Nurus autem eius, uxor Phinees, praegnans erat, vicinaque partui: et audito nuncio quod capta esset arca Dei, et mortuus esset socer suus, et vir suus, incurvavit se et peperit: irruerant enim in eam dolores subiti.',
        20: 'In ipso autem momento mortis eius, dixerunt ei quae stabant circa eam: Ne timeas, quia filium peperisti. Quae non respondit eis, neque animadvertit.',
        21: 'Et vocabit puerum, Ichabod, dicens: Translata est gloria de Israel, pro socero suo et pro viro suo;',
        22: 'et ait: Translata est gloria ab Israel, eo quod capta esset arca Dei.',
    },
    5: {
        1: 'Philisthiim autem tulerunt arcam Dei, et asportaverunt eam a Lapide adiutorii in Azotum.',
        2: 'Tuleruntque Philisthiim arcam Dei, et intulerunt eam in templum Dagon, et statuerunt eam iuxta Dagon.',
        3: 'Cumque surrexissent diluculo Azotii altera die, ecce Dagon iacebat pronus in terra ante arcam Domini: et tulerunt Dagon, et restituerunt eum in locum suum.',
        4: 'Rursumque mane die altera consurgentes, invenerunt Dagon iacentem super faciem suam in terra coram arca Domini: caput autem Dagon, et duae palmae manuum eius abscissae erant super limen:',
        5: 'porro Dagon solus truncus remanserat in loco suo. Propter hanc causam non calcant sacerdotes Dagon, et omnes qui ingrediuntur templum eius, super limen Dagon in Azoto, usque in hodiernum diem.',
        6: 'Aggravata est autem manus Domini super Azotios, et demolitus est eos: et percussit in secretiori parte natium Azotum, et fines eius. Et ebullierunt villae et agri in medio regionis illius, et nati sunt mures, et facta est confusio mortis magnae in civitate.',
        7: 'Videntes autem viri Azotii huiuscemodi plagam, dixerunt: Non maneat arca Dei Israel apud nos: quoniam dura est manus eius super nos, et super Dagon deum nostrum.',
        8: 'Et mittentes congregaverunt omnes satrapas Philisthinorum ad se, et dixerunt: Quid faciemus de arca Dei Israel? Responderuntque Gethaei: Circumducatur arca Dei Israel. Et circumduxerunt arcam Dei Israel.',
        9: 'Illis autem circumducentibus eam, fiebat manus Domini per singulas civitates interfectionis magnae nimis: et percutiebat viros uniuscuiusque urbis, a parvo usque ad maiorem, et computrescebant prominentes extales eorum. Inieruntque Gethaei consilium, et fecerunt sibi sedes pelliceas.',
        10: 'Miserunt ergo arcam Dei in Accaron. Cumque venisset arca Dei in Accaron, exclamaverunt Accaronitae, dicentes: Adduxerunt ad nos arcam Dei Israel, ut interficiat nos et populum nostrum.',
        11: 'Miserunt itaque et congregaverunt omnes satrapas Philisthinorum: qui dixerunt: Dimittite arcam Dei Israel, et revertatur in locum suum, et non interficiat nos cum populo nostro.',
        12: 'Fiebat enim pavor mortis in singulis urbibus, et gravissima valde manus Dei. viri quoque, qui mortui non fuerant, percutiebantur in secretiori parte natium: et ascendebat ululatus uniuscuiusque civitatis in caelum.',
    },
    6: {
        1: 'Fuit ergo arca Domini in regione Philisthinorum septem mensibus.',
        2: 'Et vocaverunt Philisthiim sacerdotes et divinos, dicentes: Quid faciemus de arca Domini? indicate nobis quomodo remittamus eam in locum suum. Qui dixerunt:',
        3: 'Si remittitis arcam Dei Israel, nolite dimittere eam vacuam, sed quod debetis, reddite ei pro peccato, et tunc curabimini: et scietis quare non recedat manus eius a vobis.',
        4: 'Qui dixerunt: Quid est quod pro delicto reddere debeamus ei? Responderuntque illi:',
        5: 'Iuxta numerum provinciarum Philisthinorum quinque anos aureos facietis, et quinque mures aureos: quia plaga una fuit omnibus vobis, et satrapis vestris. Facietisque similitudines anorum vestrorum, et similitudines murium, qui demoliti sunt terram. et dabitis Deo Israel gloriam: si forte relevet manum suam a vobis, et a diis vestris, et a terra vestra.',
        6: 'Quare aggravatis corda vestra, sicut aggravavit Aegyptus, et Pharao cor suum? nonne postquam percussus est, tunc dimisit eos, et abierunt?',
        7: 'Nunc ergo arripite et facite plaustrum novum unum: et duas vaccas foetas, quibus non est impositum iugum, iungite in plaustro, et recludite vitulos earum domi.',
        8: 'Tolletisque arcam Domini, et ponetis in plaustro, et vasa aurea, quae exolvistis ei pro delicto, ponetis in capsellam ad latus eius: et dimittite eam ut vadat.',
        9: 'Et aspicietis: et si quidem per viam finium suorum ascenderit contra Bethsames, ipse fecit nobis hoc malum grande: si autem, minime: sciemus quia nequaquam manus eius tetigit nos, sed casu accidit.',
        10: 'Fecerunt ergo illi hoc modo: et tollentes duas vaccas, quae lactabant vitulos, iunxerunt ad plaustrum, vitulosque earum concluserunt domi.',
        11: 'Et posuerunt arcam Dei super plaustrum, et capsellam, quae habebat mures aureos et similitudines anorum.',
        12: 'Ibant autem in directum vaccae per viam, quae ducit Bethsames, et itinere uno gradiebantur, pergentes et mugientes: et non declinabant neque ad dextram neque ad sinistram: sed et satrapae Philisthiim sequebantur usque ad terminos Bethsames.',
        13: 'Porro Bethsamitae metebant triticum in valle: et elevantes oculos suos, viderunt arcam, et gavisi sunt cum vidissent.',
        14: 'Et plaustrum venit in agrum Iosue Bethsamitae, et stetit ibi. Erat autem ibi lapis magnus, et conciderunt ligna plaustri, vaccasque imposuerunt super ea holocaustum Domino.',
        15: 'Levitae autem deposuerunt arcam Dei, et capsellam, quae erat iuxta eam, in qua erant vasa aurea, et posuerunt super lapidem grandem. Viri autem Bethsamitae obtulerunt holocausta, et immolaverunt victimas in die illa Domino.',
        16: 'Et quinque satrapae Philisthinorum viderunt, et reversi sunt in Accaron in die illa.',
        17: 'Hi sunt autem ani aurei, quos reddiderunt Philisthiim pro delicto, Domino: Azotus unum, Gaza unum, Ascalon unum, Geth unum, Accaron unum:',
        18: 'et mures aureos secundum numerum urbium Philisthiim, quinque provinciarum, ab urbe murata, usque ad villam, quae erat absque muro, et usque ad Abelmagnum, super quem posuerunt arcam Domini, quae erat usque in illum diem in agro Iosue Bethsamitis.',
        19: 'Percussit autem de viris Bethsamitibus, eo quod vidissent arcam Domini: et percussit de populo septuaginta viros, et quinquaginta millia plebis. Luxitque populus, eo quod Dominus percussisset plebem plaga magna.',
        20: 'Et dixerunt viri Bethsamitae: Quis poterit stare in conspectu Domini Dei sancti huius? et ad quem ascendet a nobis?',
        21: 'Miseruntque nuncios ad habitatores Cariathiarim, dicentes: Reduxerunt Philisthiim arcam Domini, descendite, et reducite eam ad vos.',
    },
    7: {
        1: 'Venerunt ergo viri Cariathiarim, et reduxerunt arcam Domini, et intulerunt eam in domum Abinadab in Gabaa: Eleazarum autem filium eius sanctificaverunt, ut custodiret arcam Domini.',
        2: 'Et factum est, ex qua die mansit arca Domini in Cariathiarim, multiplicati sunt dies (erat quippe iam annus vigesimus) et requievit omnis domus Israel post Dominum.',
        3: 'Ait autem Samuel ad universam domum Israel, dicens: Si in toto corde vestro revertimini ad Dominum, auferte deos alienos de medio vestri, Baalim et Astaroth: et praeparate corda vestra Domino, et servite ei soli, et eruet vos de manu Philisthiim.',
        4: 'Abstulerunt ergo filii Israel Baalim et Astaroth, et servierunt Domino soli.',
        5: 'Dixit autem Samuel: Congregate universum Israel in Masphath, ut orem pro vobis Dominum.',
        6: 'Et convenerunt in Masphath: hauseruntque aquam, et effuderunt in conspectu Domini, et ieiunaverunt in die illa, atque dixerunt ibi: Peccavimus Domino. Iudicavitque Samuel filios Israel in Masphath.',
        7: 'Et audierunt Philisthiim quod congregati essent filii Israel in Masphath, et ascenderunt satrapae Philisthinorum ad Israel. Quod cum audissent filii Israel, timuerunt a facie Philisthinorum.',
        8: 'Dixeruntque ad Samuelem: Ne cesses pro nobis clamare ad Dominum Deum nostrum, ut salvet nos de manu Philisthinorum.',
        9: 'Tulit autem Samuel agnum lactentem unum, et obtulit illum holocaustum integrum Domino: et clamavit Samuel ad Dominum pro Israel, et exaudivit eum Dominus.',
        10: 'Factum est autem, cum Samuel offerret holocaustum, Philisthiim iniere proelium contra Israel: intonuit autem Dominus fragore magno in die illa super Philisthiim, et exterruit eos, et caesi sunt a filiis Israel.',
        11: 'Egressique viri Israel de Masphath persecuti sunt Philisthaeos, et percusserunt eos usque ad locum, qui erat subter Bethchar.',
        12: 'Tulit autem Samuel lapidem unum, et posuit eum inter Masphath et inter Sen: et vocavit nomen loci illius, Lapis adiutorii. Dixitque: Hucusque auxiliatus est nobis Dominus.',
        13: 'Et humiliati sunt Philisthiim, nec apposuerunt ultra ut venirent in terminos Israel. Facta est itaque manus Domini super Philisthaeos, cunctis diebus Samuelis.',
        14: 'Et redditae sunt urbes, quas tulerant Philisthiim ab Israel, Israeli, ab Accaron usque Geth, et terminos suos: liberavitque Israel de manu Philisthinorum, eratque pax inter Israel et Amorrhaeum.',
        15: 'Iudicabat quoque Samuel Israelem cunctis diebus vitae suae:',
        16: 'et ibat per singulos annos circuiens Bethel et Galgala et Masphath, et iudicabat Israelem in supradictis locis.',
        17: 'Revertebaturque in Ramatha: ibi enim erat domus eius, et ibi iudicabat Israelem: aedificavit etiam ibi altare Domino.',
    },
    8: {
        1: 'Factum est autem cum senuisset Samuel, posuit filios suos iudices Israel.',
        2: 'Fuitque nomen filii eius primogeniti Ioel: et nomen secundi Abia, iudicum in Bersabee.',
        3: 'Et non ambulaverunt filii illius in viis eius: sed declinaverunt post avaritiam, acceperuntque munera, et perverterunt iudicium.',
        4: 'Congregati ergo universi maiores natu Israel, venerunt ad Samuelem in Ramatha.',
        5: 'Dixeruntque ei: Ecce tu senuisti, et filii tui non ambulant in viis tuis: constitue nobis regem, ut iudicet nos, sicut et universae habent nationes.',
        6: 'Displicuit sermo in oculis Samuelis, eo quod dixissent: Da nobis regem, ut iudicet nos. Et oravit Samuel ad Dominum.',
        7: 'Dixit autem Dominus ad Samuelem: Audi vocem populi in omnibus quae loquuntur tibi. non enim te abiecerunt, sed me, ne regnem super eos.',
        8: 'Iuxta omnia opera sua, quae fecerunt a die qua eduxi eos de Aegypto usque ad diem hanc: sicut dereliquerunt me, et servierunt diis alienis, sic faciunt etiam tibi.',
        9: 'Nunc ergo vocem eorum audi: verumtamen contestare eos, et praedic eis ius regis, qui regnaturus est super eos.',
        10: 'Dixit itaque Samuel omnia verba Domini ad populum, qui petierat a se regem,',
        11: 'et ait: Hoc erit ius regis, qui imperaturus est vobis: filios vestros tollet, et ponet in curribus suis, facietque sibi equites et praecursores quadrigarum suarum,',
        12: 'et constituet sibi tribunos, et centuriones, et aratores agrorum suorum, et messores segetum, et fabros armorum et curruum suorum.',
        13: 'Filias quoque vestras faciet sibi unguentarias, et focarias, et panificas.',
        14: 'Agros quoque vestros, et vineas, et oliveta optima tollet, et dabit servis suis.',
        15: 'Sed et segetes vestras, et vinearum reditus addecimabit, ut det eunuchis et famulis suis.',
        16: 'Servos etiam vestros, et ancillas, et iuvenes optimos, et asinos, auferet, et ponet in opere suo.',
        17: 'Greges quoque vestros addecimabit, vosque eritis ei servi.',
        18: 'Et clamabitis in die illa a facie regis vestri, quem elegistis vobis: et non exaudiet vos Dominus in die illa, quia petistis vobis regem.',
        19: 'Noluit autem populus audire vocem Samuelis, sed dixerunt: Nequaquam: rex enim erit super nos,',
        20: 'et erimus nos quoque sicut omnes gentes: et iudicabit nos rex noster, et egredietur ante nos, et pugnabit bella nostra pro nobis.',
        21: 'Et audivit Samuel omnia verba populi, et locutus est ea in auribus Domini.',
        22: 'Dixit autem Dominus ad Samuelem: Audi vocem eorum, et constitue super eos regem. Et ait Samuel ad viros Israel: Vadat unusquisque in civitatem suam.',
    },
    9: {
        1: 'Et erat vir de Beniamin nomine Cis, filius Abiel, filii Seor, filii Bechorath, filii Aphia, filii viri Iemini, fortis robore.',
        2: 'Et erat ei filius vocabulo Saul, electus et bonus: et non erat vir de filiis Israel melior illo. ab humero et sursum eminebat super omnem populum.',
        3: 'Perierant autem asinae Cis patris Saul: et dixit Cis ad Saul filium suum: Tolle tecum unum de pueris, et consurgens vade, et quaere asinas. Qui cum transissent per montem Ephraim,',
        4: 'et per terram Salisa, et non invenissent, transierunt etiam per Terram Salim, et non erant: sed et per Terram Iemini, et minime repererunt.',
        5: 'Cum autem venissent in Terram Suph, dixit Saul ad puerum, qui erat cum eo: Veni et revertamur, ne forte dimiserit pater meus asinas, et solicitus sit pro nobis.',
        6: 'Qui ait ei: Ecce vir Dei est in civitate hac, vir nobilis: omne, quod loquitur, sine ambiguitate venit. nunc ergo eamus illuc, si forte indicet nobis de via nostra, propter quam venimus.',
        7: 'Dixitque Saul ad puerum suum: Ecce ibimus: quid feremus ad virum Dei? panis defecit in sitachiis nostris: et sportulam non habemus, ut demus homini Dei, nec quidquam aliud.',
        8: 'Rursum puer respondit Sauli, et ait: Ecce inventa est in manu mea, quarta pars stateris argenti, demus homini Dei, ut indicet nobis viam nostram.',
        9: '(Olim in Israel sic loquebatur unusquisque vadens consulere Deum: Venite, et eamus ad Videntem. Qui enim Propheta dicitur hodie, vocabatur olim Videns.)',
        10: 'Et dixit Saul ad puerum suum: Optimus sermo tuus, Veni, eamus. Et ierunt in civitatem, in qua erat vir Dei.',
        11: 'Cumque ascenderent clivum civitatis, invenerunt puellas egredientes ad hauriendam aquam, et dixerunt eis: Num hic est Videns?',
        12: 'Quae respondentes, dixerunt illis: Hic est: ecce ante te, festina nunc: hodie enim venit in civitatem, quia sacrificium est hodie populi in excelso.',
        13: 'Ingredientes urbem, statim invenietis eum antequam ascendat excelsum ad vescendum. neque enim comesurus est populus donec ille veniat: quia ipse benedicit hostiae, et deinceps comedunt qui vocati sunt. Nunc ergo conscendite, quia hodie reperietis eum.',
        14: 'Et ascenderunt in civitatem. Cumque illi ambularent in medio urbis, apparuit Samuel egrediens obviam eis, ut ascenderet in excelsum.',
        15: 'Dominus autem revelaverat auriculam Samuelis ante unam diem quam veniret Saul, dicens:',
        16: 'Hac ipsa hora, quae nunc est, cras mittam virum ad te de Terra Beniamin, et unges eum ducem super populum meum Israel: et salvabit populum meum de manu Philisthinorum: quia respexi populum meum, venit enim clamor eorum ad me.',
        17: 'Cumque aspexisset Samuel Saulem, Dominus dixit ei: Ecce, vir, quem dixeram tibi, iste dominabitur populo meo.',
        18: 'Accessit autem Saul ad Samuelem in medio portae, et ait: Indica, oro, mihi, ubi est domus Videntis.',
        19: 'Et respondit Samuel Sauli dicens: Ego sum Videns. ascende ante me in excelsum, ut comedatis mecum hodie, et dimittam te mane: et omnia, quae sunt in corde tuo, indicabo tibi.',
        20: 'Et de asinis, quas nudiustertius perdidisti, ne solicitus sis, quia inventae sunt. Et cuius erunt optima quaeque Israel? nonne tibi et omni domui patris tui?',
        21: 'Respondens autem Saul, ait: Numquid non filius Iemini ego sum de minima tribu Israel, et cognatio mea novissima inter omnes familias de tribu Beniamin? quare ergo locutus es mihi sermonem istum?',
        22: 'Assumens itaque Samuel Saulem, et puerum eius, introduxit eos in triclinium, et dedit eis locum in capite eorum, qui fuerant invitati. erant enim quasi triginta viri.',
        23: 'Dixitque Samuel coco: Da partem, quam dedi tibi, et praecepi ut reponeres seorsum apud te.',
        24: 'Levavit autem cocus armum, et posuit ante Saul. Dixitque Samuel: Ecce quod remansit, pone ante te, et comede: quia de industria servatum est tibi, quando populum vocavi. Et comedit Saul cum Samuele in die illa.',
        25: 'Et descenderunt de excelso in oppidum, et locutus est cum Saule in solario: stravitque Saul in solario, et dormivit.',
        26: 'Cumque mane surrexissent, et iam elucesceret, vocavit Samuel Saulem in solario, dicens: Surge, ut dimittam te. Et surrexit Saul: egressique sunt ambo, ipse videlicet, et Samuel.',
        27: 'Cumque descenderent in extrema parte civitatis, Samuel dixit ad Saul: Dic puero ut antecedat nos, et transeat: tu autem subsiste paulisper, ut indicem tibi verbum Domini.',
    },
    10: {
        1: 'Tulit autem Samuel lenticulam olei, et effudit super caput eius, et deosculatus est eum, et ait: Ecce, unxit te Dominus super hereditatem suam in principem, et liberabis populum suum de manibus inimicorum eius, qui in circuitu eius sunt. Et hoc tibi signum, quia unxit te Deus in principem.',
        2: 'Cum abieris hodie a me, invenies duos viros iuxta sepulchrum Rachel in finibus Beniamin, in Meridie, dicentque tibi: Inventae sunt asinae, ad quas ieras perquirendas: et intermissis pater tuus asinis, solicitus est pro vobis, et dicit: Quid faciam de filio meo?',
        3: 'Cumque abieris inde, et ultra transieris, et veneris ad quercum Thabor, invenient te ibi tres viri ascendentes ad Deum in Bethel, unus portans tres hoedos, et alius tres tortas panis, et alius portans lagenam vini.',
        4: 'Cumque te salutaverint, dabunt tibi duos panes, et accipies de manu eorum.',
        5: 'Post haec venies in collem Dei, ubi est statio Philisthinorum: et cum ingressus fueris ibi urbem, obvium habebis gregem prophetarum descendentium de excelso, et ante eos psalterium et tympanum, et tibiam, et citharam, ipsosque prophetantes.',
        6: 'Et insiliet in te Spiritus Domini, et prophetabis cum eis, et mutaberis in virum alium.',
        7: 'Quando ergo evenerint signa haec omnia tibi, fac quaecumque invenerit manus tua, quia Dominus tecum est.',
        8: 'Et descendes ante me in Galgala, (ego quippe descendam ad te) ut offeras oblationem, et immoles victimas pacificas: septem diebus expectabis, donec veniam ad te, et ostendam tibi quid facias.',
        9: 'Itaque cum avertisset humerum suum ut abiret a Samuele, immutavit ei Deus cor aliud, et venerunt omnia signa haec in die illa.',
        10: 'Veneruntque ad praedictum collem, et ecce cuneus prophetarum obvius ei: et insiluit super eum Spiritus Domini, et prophetavit in medio eorum.',
        11: 'Videntes autem omnes qui noverant eum heri et nudiustertius, quod esset cum prophetis, et prophetaret, dixerunt ad invicem: Quaenam res accidit filio Cis? num et Saul inter prophetas?',
        12: 'Responditque alius ad alterum, dicens: Et quis pater eius? propterea versum est in proverbium: Num et Saul inter prophetas?',
        13: 'Cessavit autem prophetare, et venit ad excelsum.',
        14: 'Dixitque patruus Saul ad eum, et ad puerum eius: Quo abistis? Qui responderunt: Quaerere asinas: quas cum non reperissemus, venimus ad Samuelem.',
        15: 'Et dixit ei patruus suus: Indica mihi quid dixerit tibi Samuel.',
        16: 'Et ait Saul ad patruum suum: Indicavit nobis quia inventae essent asinae. De sermone autem regni non indicavit ei quem locutus fuerat ei Samuel.',
        17: 'Et convocavit Samuel populum ad Dominum in Maspha:',
        18: 'et ait ad filios Israel: Haec dicit Dominus Deus Israel: Ego eduxi Israel de Aegypto, et erui vos de manu Aegyptiorum, et de manu omnium regum qui affligebant vos.',
        19: 'Vos autem hodie proiecistis Deum vestrum, qui solus salvavit vos de universis malis et tribulationibus vestris: et dixistis: Nequaquam: sed regem constitue super nos. Nunc ergo state coram Domino per tribus vestras, et per familias.',
        20: 'Et applicuit Samuel omnes tribus Israel, et cecidit sors tribus Beniamin.',
        21: 'Et applicuit tribum Beniamin et cognationes eius, et cecidit cognatio Metri, et pervenit usque ad Saul filium Cis. Quaesierunt ergo eum, et non est inventus.',
        22: 'Et consuluerunt post haec Dominum utrumnam venturus esset illuc. Responditque Dominus: Ecce absconditus est domi.',
        23: 'Cucurrerunt itaque et tulerunt eum inde: stetitque in medio populi, et altior fuit universo populo ab humero et sursum.',
        24: 'Et ait Samuel ad omnem populum: Certe videtis quem elegit Dominus, quoniam non sit similis illi in omni populo. Et clamavit omnis populus, et ait: Vivat rex.',
        25: 'Locutus est autem Samuel ad populum legem regni, et scripsit in libro, et reposuit coram Domino: et dimisit Samuel omnem populum, singulos in domum suam.',
        26: 'Sed et Saul abiit in domum suam in Gabaa: et abiit cum eo pars exercitus, quorum tetigerat Deus corda.',
        27: 'Filii vero Belial dixerunt: Num salvare nos poterit iste? Et despexerunt eum, et non attulerunt ei munera: ille vero dissimulabat se audire.',
    },
    11: {
        1: 'Et factum est quasi post mensem, ascendit Naas Ammonites, et pugnare coepit adversum Iabes Galaad. Dixeruntque omnes viri Iabes ad Naas: Habeto nos foederatos, et serviemus tibi.',
        2: 'Et respondit ad eos Naas Ammonites: In hoc feriam vobiscum foedus, ut eruam omnium vestrum oculos dextros, ponamque vos opprobrium in universo Israel.',
        3: 'Et dixerunt ad eum seniores Iabes: Concede nobis septem dies, ut mittamus nuncios ad universos terminos Israel: et si non fuerit qui defendat nos, egrediemur ad te.',
        4: 'Venerunt ergo nuncii in Gabaa Saulis: et locuti sunt verba haec, audiente populo: et levavit omnis populus vocem suam, et flevit.',
        5: 'Et ecce Saul veniebat, sequens boves de agro, et ait: Quid habet populus quod plorat? Et narraverunt ei verba virorum Iabes.',
        6: 'Et insilivit Spiritus Domini in Saul, cum audisset verba haec, et iratus est furor eius nimis.',
        7: 'Et assumens utrumque bovem, concidit in frustra, misitque in omnes terminos Israel per manum nunciorum, dicens: Quicumque non exierit, et secutus fuerit Saul et Samuel, sic fiet bobus eius. Invasit ergo timor Domini populum, et egressi sunt quasi vir unus.',
        8: 'Et recensuit eos in Bezech: fueruntque filiorum Israel trecenta millia: virorum autem Iuda triginta millia.',
        9: 'Et dixerunt nunciis qui venerant: Sic dicetis viris, qui sunt in Iabes Galaad: Cras erit vobis salus, cum incaluerit sol. Venerunt ergo nuncii, et annunciaverunt viris Iabes: qui laetati sunt.',
        10: 'Et dixerunt: Mane exibimus ad vos: et facietis nobis omne quod placuerit vobis.',
        11: 'Et factum est, cum dies crastinus venisset, constituit Saul populum in tres partes: et ingressus est media castra in vigilia matutina, et percussit Ammon usque dum incalesceret dies: reliqui autem dispersi sunt, ita ut non relinquerentur in eis duo pariter.',
        12: 'Et ait populus ad Samuelem: Quis est iste qui dixit: Saul num regnabit super nos? Date viros, et interficiemus eos.',
        13: 'Et ait Saul: Non occidetur quisquam in die hac, quia hodie fecit Dominus salutem in Israel.',
        14: 'Dixit autem Samuel ad populum: Venite, et eamus in Galgala, et innovemus ibi regnum.',
        15: 'Et perrexit omnis populus in Galgala, et fecerunt ibi regem Saul coram Domino in Galgala, et immolaverunt ibi victimas pacificas coram Domino. Et laetatus est ibi Saul, et cuncti viri Israel nimis.',
    },
    12: {
        1: 'Dixit autem Samuel ad universum Israel: Ecce audivi vocem vestram iuxta omnia quae locuti estis ad me, et constitui super vos regem.',
        2: 'Et nunc rex graditur ante vos: ego autem senui, et incanui: porro filii mei vobiscum sunt: itaque conversatus coram vobis ab adolescentia mea usque ad hanc diem, ecce praesto sum.',
        3: 'Loquimini de me coram Domino, et coram Christo eius, utrum bovem cuiusquam tulerim, aut asinum: si quempiam calumniatus sum, si oppressi aliquem, si de manu cuiusquam munus accepi: et contemnam illud hodie, restituamque vobis.',
        4: 'Et dixerunt: Non es calumniatus nos, neque oppressisti, neque tulisti de manu alicuius quippiam.',
        5: 'Dixitque ad eos: Testis est Dominus adversum vos, et testis Christus eius in die hac, quia non inveneritis in manu mea quippiam. Et dixerunt: Testis.',
        6: 'Et ait Samuel ad populum: Dominus qui fecit Moysen et Aaron, et eduxit patres nostros de Terra Aegypti, adest.',
        7: 'Nunc ergo state, ut iudicio contendam adversum vos coram Domino de omnibus misericordiis Domini, quas fecit vobiscum et cum patribus vestris:',
        8: 'quo modo Iacob ingressus est in Aegyptum, et clamaverunt patres vestri ad Dominum: et misit Dominus Moysen et Aaron, et eduxit patres vestros de Aegypto: et collocavit eos in loco hoc.',
        9: 'Qui obliti sunt Domini Dei sui, et tradidit eos in manu Sisarae magistri militiae Hasor, et in manu Philisthinorum, et in manu regis Moab, et pugnaverunt adversum eos.',
        10: 'Postea autem clamaverunt ad Dominum, et dixerunt: Peccavimus, quia dereliquimus Dominum, et servivimus Baalim et Astaroth: nunc ergo erue nos de manu inimicorum nostrorum, et serviemus tibi.',
        11: 'Et misit Dominus Ierobaal, et Badan, et Samson, et Barac, et Iephte, et Samuel, et eruit vos de manu inimicorum vestrorum per circuitum, et habitastis confidenter.',
        12: 'Videntes autem quod Naas rex filiorum Ammon venisset adversum vos, dixistis mihi: Nequaquam, sed rex imperabit nobis: cum Dominus Deus vester regnaret in vobis.',
        13: 'Nunc ergo praesto est rex vester, quem elegistis et petistis: ecce dedit vobis Dominus regem.',
        14: 'Si timueritis Dominum, et servieritis ei, et audieritis vocem eius, et non exasperaveritis os Domini: eritis et vos, et rex qui imperat vobis, sequentes Dominum Deum vestrum.',
        15: 'si autem non audieritis vocem Domini, sed exasperaveritis sermones eius, erit manus Domini super vos, sicut et super patres vestros.',
        16: 'Sed et nunc state, et videte rem istam grandem quam facturus est Dominus in conspectu vestro.',
        17: 'Numquid non messis tritici est hodie? invocabo Dominum, et dabit voces et pluvias: et scietis, et videbitis quia grande malum feceritis vobis in conspectu Domini, petentes super vos regem.',
        18: 'Et clamavit Samuel ad Dominum, et dedit Dominus voces et pluvias in illa die.',
        19: 'Et timuit omnis populus nimis Dominum et Samuelem, et dixit universus populus ad Samuelem: Ora pro servis tuis ad Dominum Deum tuum, ut non moriamur. addidimus enim universis peccatis nostris malum, ut peteremus nobis regem.',
        20: 'Dixit autem Samuel ad populum: Nolite timere, vos fecistis universum malum hoc: verumtamen nolite recedere a tergo Domini, sed servite Domino in omni corde vestro.',
        21: 'Et nolite declinare post vana, quae non proderunt vobis, neque eruent vos, quia vana sunt.',
        22: 'Et non derelinquet Dominus populum suum propter nomen suum magnum: quia iuravit Dominus facere vos sibi populum.',
        23: 'Absit autem a me hoc peccatum in Domino, ut cessem orare pro vobis, et docebo vos viam bonam et rectam.',
        24: 'Igitur timete Dominum, et servite ei in veritate, et ex toto corde vestro. vidistis enim magnifica quae in vobis gesserit.',
        25: 'Quod si perseveraveritis in malitia: et vos et rex vester pariter peribitis.',
    },
    13: {
        1: 'Filius unius anni erat Saul cum regnare coepisset, duobus autem annis regnavit super Israel.',
        2: 'Et elegit sibi Saul tria millia de Israel: et erant cum Saul duo millia in Machmas, et in monte Bethel: mille autem cum Ionatha in Gabaa Beniamin. porro ceterum populum remisit unumquemque in tabernacula sua.',
        3: 'Et percussit Ionathas stationem Philisthinorum, quae erat in Gabaa. Quod cum audissent Philisthiim, Saul cecinit buccina in omni terra, dicens: Audiant Hebraei.',
        4: 'Et universus Israel audivit huiuscemodi famam: Percussit Saul stationem Philisthinorum: et erexit se Israel adversus Philisthiim. Clamavit ergo populus post Saul in Galgala.',
        5: 'Et Philisthiim congregati sunt ad proeliandum contra Israel, triginta millia curruum, et sex millia equitum, et reliquum vulgus, sicut arena quae est in littore maris plurima. Et ascendentes castrametati sunt in Machmas ad Orientem Bethaven.',
        6: 'Quod cum vidissent viri Israel se in arcto positos, (afflictus enim erat populus) absconderunt se in speluncis, et in abditis, in petris quoque, et in antris, et in cisternis.',
        7: 'Hebraei autem transierunt Iordanem in Terram Gad et Galaad. Cumque adhuc esset Saul in Galgala, universus populus perterritus est, qui sequebatur eum.',
        8: 'Et expectavit septem diebus iuxta placitum Samuelis, et non venit Samuel in Galgala, dilapsusque est populus ab eo.',
        9: 'Ait ergo Saul: Afferte mihi holocaustum, et pacifica. Et obtulit holocaustum.',
        10: 'Cumque complesset offerens holocaustum, ecce Samuel veniebat: et egressus est Saul obviam ei ut salutaret eum.',
        11: 'Locutusque est ad eum Samuel: Quid fecisti? Respondit Saul: Quia vidi quod populus dilaberetur a me, et tu non veneras iuxta placitos dies, porro Philisthiim congregati fuerant in Machmas,',
        12: 'dixi: Nunc descendent Philisthiim ad me in Galgala, et faciem Domini non placavi. Necessitate compulsus, obtuli holocaustum.',
        13: 'Dixitque Samuel ad Saul: Stulte egisti, nec custodisti mandata Domini Dei tui, quae praecepit tibi. Quod si non fecisses, iam nunc praeparasset Dominus regnum tuum super Israel in sempiternum,',
        14: 'sed nequaquam regnum tuum ultra consurget. Quaesivit Dominus sibi virum iuxta cor suum: et praecepit ei Dominus ut esset dux super populum suum, eo quod non servaveris quae praecepit Dominus.',
        15: 'Surrexit autem Samuel, et ascendit de Galgalis in Gabaa Beniamin. Et reliqui populi ascenderunt post Saul obviam populo, qui expugnabant eos venientes de Galgala in Gabaa, in colle Beniamin. Et recensuit Saul populum, qui inventi fuerant cum eo, quasi sexcentos viros.',
        16: 'Et Saul et Ionathas filius eius, populusque qui inventus fuerat cum eis, erat in Gabaa Beniamin: porro Philisthiim consederant in Machmas.',
        17: 'Et egressi sunt ad praedandum de castris Philisthinorum tres cunei. Unus cuneus pergebat contra viam Ephra ad Terram Sual.',
        18: 'porro alius ingrediebatur per viam Beth horon. tertius autem verterat se ad iter termini in terra Sabaa imminentis valli Seboim contra desertum.',
        19: 'Porro faber ferrarius non inveniebatur in omni Terra Israel. caverant enim Philisthiim, ne forte facerent Hebraei gladium aut lanceam.',
        20: 'Descendebat ergo omnis Israel ad Philisthiim, ut exacueret unusquisque vomerem suum, et ligonem et securim et sarculum.',
        21: 'Retusae itaque erant acies vomerum, et ligonum, et tridentum, et securium, usque ad stimulum corrigendum.',
        22: 'Cumque venisset dies proelii, non est inventus ensis et lancea in manu totius populi, qui erat cum Saule et Ionatha, excepto Saul et Ionatha filio eius.',
        23: 'Egressa est autem statio Philisthiim, ut transcenderet in Machmas.',
    },
    14: {
        1: 'Et accidit quadam die ut diceret Ionathas filius Saul ad adolescentem armigerum suum: Veni, et transeamus ad stationem Philisthinorum, quae est trans locum illum. Patri autem suo hoc ipsum non indicavit.',
        2: 'Porro Saul morabatur in extrema parte Gabaa sub malogranato, quae erat in agro Gabaa: et erat populus cum eo quasi sexcentorum virorum.',
        3: 'Et Achias filius Achitob fratris Ichabod filii Phinees, qui ortus fuerat ex Heli sacerdote Domini in Silo, portabat ephod. Sed et populus ignorabat quo isset Ionathas.',
        4: 'Erant autem inter ascensus, per quos nitebatur Ionathas transire ad stationem Philisthinorum, eminentes petrae ex utraque parte, et quasi in modum dentium scopuli hinc et inde praerupti, nomen uni Boses, et nomen alteri Sene:',
        5: 'unus scopulus prominens ad Aquilonem ex adverso Machmas, et alter ad Meridiem contra Gabaa.',
        6: 'Dixit autem Ionathas ad adolescentem armigerum suum: Veni, transeamus ad stationem incircumcisorum horum, si forte faciat Dominus pro nobis: quia non est Domino difficile salvare, vel in multis, vel in paucis.',
        7: 'Dixitque ei armiger suus: Fac omnia, quae placent animo tuo: perge quo cupis, et ero tecum ubicumque volueris.',
        8: 'Et ait Ionathas: Ecce nos transimus ad viros istos. Cumque apparuerimus eis,',
        9: 'si taliter locuti fuerint ad nos, manete donec veniamus ad vos: stemus in loco nostro, nec ascendamus ad eos.',
        10: 'Si autem dixerint: Ascendite ad nos: ascendamus, quia tradidit eos Dominus in manibus nostris, hoc erit nobis signum.',
        11: 'Apparuit igitur uterque stationi Philisthinorum: dixeruntque Philisthiim: En Hebraei egrediuntur de cavernis, in quibus absconditi fuerant.',
        12: 'Et locuti sunt viri de statione ad Ionathan, et ad armigerum eius, dixeruntque: Ascendite ad nos, et ostendemus vobis rem. Et ait Ionathas ad armigerum suum: Ascendamus, sequere me: tradidit enim Dominus eos in manus Israel.',
        13: 'Ascendit autem Ionathas manibus et pedibus reptans, et armiger eius post eum. Itaque alii cadebant ante Ionathan, alios armiger eius interficiebat sequens eum.',
        14: 'Et facta est plaga prima, qua percussit Ionathas et armiger eius, quasi viginti virorum in media parte iugeris, quam par boum in die arare consuevit.',
        15: 'Et factum est miraculum in castris, et per agros: sed et omnis populus stationis eorum, qui ierant ad praedandum, obstupuit, et conturbata sunt castra: et accidit quasi miraculum a Deo.',
        16: 'Et respexerunt speculatores Saul, qui erant in Gabaa Beniamin, et ecce multitudo prostrata, et huc illucque diffugiens.',
        17: 'Et ait Saul populo, qui erat cum eo: Requirite, et videte quis abierit ex nobis. Cumque requisissent, repertum est non adesse Ionathan, et armigerum eius.',
        18: 'Et ait Saul ad Achiam: Applica arcam Dei. (Erat enim ibi arca Dei in die illa cum filiis Israel.)',
        19: 'Cumque loqueretur Saul ad sacerdotem, tumultus magnus exortus est in castris Philisthinorum: crescebatque paulatim, et clarius resonabat. Et ait Saul ad sacerdotem: Contrahe manum tuam.',
        20: 'Conclamavit ergo Saul, et omnis populus, qui erat cum eo, et venerunt usque ad locum certaminis: et ecce versus fuerat gladius uniuscuiusque ad proximum suum, et caedes magna nimis.',
        21: 'Sed et Hebraei qui fuerant cum Philisthiim heri et nudiustertius, ascenderantque cum eis in castris, reversi sunt ut essent cum Israel, qui erant cum Saul et Ionatha.',
        22: 'Omnes quoque Israelitae, qui se absconderant in monte Ephraim, audientes quod fugissent Philisthaei, sociaverunt se cum suis in praelio. Et erant cum Saul, quasi decem millia virorum.',
        23: 'Et salvavit Dominus in die illa Israel. pugna autem pervenit usque ad Bethaven.',
        24: 'Et viri Israel sociati sunt sibi in die illa: adiuravit autem Saul populum, dicens: Maledictus vir, qui comederit panem usque ad vesperam, donec ulciscar de inimicis meis. Et non manducavit universus populus panem:',
        25: 'omneque terrae vulgus venit in saltum, in quo erat mel super faciem agri.',
        26: 'Ingressus est itaque populus saltum, et apparuit fluens mel, nullusque applicuit manum ad os suum. timebat enim populus iuramentum.',
        27: 'Porro Ionathas non audierat cum adiuraret pater eius populum: extenditque summitatem virgae, quam habebat in manu, et intinxit in favum mellis: et convertit manum suam ad os suum, et illuminati sunt oculi eius.',
        28: 'Respondensque unus de populo, ait: Iureiurando constrinxit pater tuus populum, dicens: Maledictus vir, qui comederit panem hodie. (defecerat autem populus)',
        29: 'Dixitque Ionathas: Turbavit pater meus terram: vidistis ipsi quia illuminati sunt oculi mei, eo quod gustaverim paululum de melle isto:',
        30: 'quanto magis si comedisset populus de praeda inimicorum suorum, quam reperit? nonne maior plaga facta fuisset in Philisthiim?',
        31: 'Percusserunt ergo in die illa Philisthaeos a Machmis usque in Aialon. Defatigatus est autem populus nimis:',
        32: 'et versus ad praedam tulit oves, et boves, et vitulos, et mactaverunt in terra: comeditque populus cum sanguine.',
        33: 'Nunciaverunt autem Sauli dicentes quod populus peccasset Domino, comedens cum sanguine. Qui ait: Praevaricati estis: volvite ad me iam nunc saxum grande.',
        34: 'Et dixit Saul: Dispergimini in vulgus, et dicite eis ut adducat ad me unusquisque bovem suum et arietem, et occidite super istud, et vescimini, et non peccabitis Domino comedentes cum sanguine. Adduxit itaque omnis populus unusquisque bovem in manu sua usque ad noctem: et occiderunt ibi.',
        35: 'Aedificavit autem Saul altare Domino; tuncque primum coepit aedificare altare Domino.',
        36: 'Et dixit Saul: Irruamus super Philisthaeos nocte, et vastemus eos usquedum illucescat mane, nec relinquamus ex eis virum. Dixitque populus: Omne quod bonum videtur in oculis tuis, fac. Et ait sacerdos: Accedamus huc ad Deum.',
        37: 'Et consuluit Saul Dominum: Num persequar Philisthiim? si trades eos in manus Israel? Et non respondit ei in die illa.',
        38: 'Dixitque Saul: Applicate huc universos angulos populi: et scitote, et videte per quem acciderit peccatum hoc hodie.',
        39: 'Vivit Dominus salvator Israel, quia si per Ionathan filium meum factum est, absque retractione morietur. Ad quod nullus contradixit ei de omni populo.',
        40: 'Et ait ad universum Israel: Separamini vos in partem unam, et ego cum Ionatha filio meo ero in parte altera. Responditque populus ad Saul: Quod bonum videtur in oculis tuis, fac.',
        41: 'Et dixit Saul ad Dominum Deum Israel: Domine Deus Israel da indicium: quid est quod non responderis servo tuo hodie? Si in me, aut in Ionatha filio meo est iniquitas haec, da ostensionem: aut si haec iniquitas est in populo tuo, da sanctitatem. Et deprehensus est Ionathas et Saul, populus autem exivit.',
        42: 'Et ait Saul: Mittite sortem inter me, et inter Ionathan filium meum. Et captus est Ionathas.',
        43: 'Dixit autem Saul ad Ionathan: Indica mihi quid feceris. Et indicavit ei Ionathas, et ait: Gustans gustavi in summitate virgae, quae erat in manu mea, paululum mellis, et ecce ego morior.',
        44: 'Et ait Saul: Haec faciat mihi Deus, et haec addat, quia morte morieris Ionatha.',
        45: 'Dixitque populus ad Saul: Ergone Ionathas morietur, qui fecit salutem hanc magnam in Israel? hoc nefas est: vivit Dominus, si ceciderit capillus de capite eius in terram, quia cum Deo operatus est hodie. Liberavit ergo populus Ionathan, ut non moreretur.',
        46: 'Recessitque Saul, nec persecutus est Philisthiim: porro Philisthiim abierunt in loca sua.',
        47: 'Et Saul, confirmato regno super Israel, pugnabat per circuitum adversum omnes inimicos eius, contra Moab, et filios Ammon, et Edom, et reges Soba, et Philisthaeos: et quocumque se verterat, superabat.',
        48: 'Congregatoque exercitu, percussit Amalec, et eruit Israel de manu vastatorum eius.',
        49: 'Fuerunt autem filii Saul, Ionathas et Iessui, et Melchisua: et nomina duarum filiarum eius, nomen primogenitae Merob, et nomen minoris Michol.',
        50: 'Et nomen uxoris Saul, Achinoam filia Achimaas: et nomen principis militiae eius Abner, filius Ner, patruelis Saul.',
        51: 'Porro Cis fuit pater Saul, et Ner pater Abner, filius Abiel.',
        52: 'Erat autem bellum potens adversum Philisthaeos omnibus diebus Saul. Nam quemcumque viderat Saul virum fortem, et aptum ad praelium, sociabat eum sibi.',
    },
    15: {
        1: 'Et dixit Samuel ad Saul: Me misit Dominus, ut ungerem te in regem super populum eius Israel: nunc ergo audi vocem Domini:',
        2: 'Haec dicit Dominus exercituum: Recensui quaecumque fecit Amalec Israeli: quomodo restitit ei in via cum ascenderet de Aegypto.',
        3: 'Nunc ergo vade, et percute Amalec, et demolire universa eius: non parcas ei, et non concupiscas ex rebus ipsius aliquid: sed interfice a viro usque ad mulierem, et parvulum atque lactentem, bovem et ovem, camelum et asinum.',
        4: 'Praecepit itaque Saul populo, et recensuit eos quasi agnos: ducenta millia peditum, et decem millia virorum Iuda.',
        5: 'Cumque venisset Saul usque ad civitatem Amalec, tetendit insidias in torrente.',
        6: 'Dixitque Saul Cinaeo: Abite, recedite, atque descendite ab Amalec: ne forte involvam te cum eo. tu enim fecisti misericordiam cum omnibus filiis Israel, cum ascenderent de Aegypto. Et recessit Cinaeus de medio Amalec.',
        7: 'Percussitque Saul Amalec ab Hevila, donec venias ad Sur, quae est e regione Aegypti.',
        8: 'Et apprehendit Agag regem Amalec vivum: omne autem vulgus interfecit in ore gladii.',
        9: 'Et pepercit Saul, et populus Agag, et optimis gregibus ovium et armentorum, et vestibus et arietibus, et universis, quae pulchra erant, nec voluerunt disperdere ea: quidquid vero vile fuit et reprobum, hoc demoliti sunt.',
        10: 'Factum est autem verbum Domini ad Samuel, dicens:',
        11: 'Poenitet me quod constituerim Saul regem: quia dereliquit me, et verba mea opere non implevit. Contristatusque est Samuel, et clamavit ad Dominum tota nocte.',
        12: 'Cumque de nocte surrexisset Samuel, ut iret ad Saul mane, nunciatum est Samueli, eo quod venisset Saul in Carmelum, et erexisset sibi fornicem triumphalem, et reversus transisset, descendissetque in Galgala. Venit ergo Samuel ad Saul, et Saul offerebat holocaustum Domino de initiis praedarum quae attulerat ex Amalec.',
        13: 'Et cum venisset Samuel ad Saul, dixit ei Saul: Benedictus tu Domino, implevi verbum Domini.',
        14: 'Dixitque Samuel: Et quae est haec vox gregum, quae resonat in auribus meis, et armentorum, quam ego audio?',
        15: 'Et ait Saul: De Amalec adduxerunt ea: pepercit enim populus melioribus ovibus et armentis ut immolarentur Domino Deo tuo, reliqua vero occidimus.',
        16: 'Ait autem Samuel ad Saul: Sine me, et indicabo tibi quae locutus sit Dominus ad me nocte. Dixitque ei: Loquere.',
        17: 'Et ait Samuel: Nonne cum parvulus esses in oculis tuis, caput in tribubus Israel factus es? unxitque te Dominus in regem super Israel,',
        18: 'et misit te Dominus in viam, et ait: Vade, et interfice peccatores Amalec, et pugnabis contra eos usque ad internecionem eorum.',
        19: 'Quare ergo non audisti vocem Domini: sed versus ad praedam es, et fecisti malum in oculis Domini?',
        20: 'Et ait Saul ad Samuelem: Immo audivi vocem Domini, et ambulavi in via per quam misit me Dominus, et adduxi Agag regem Amalec, et Amalec interfeci.',
        21: 'Tulit autem de praeda populus oves et boves, primitias eorum quae caesa sunt, ut immolet Domino Deo suo in Galgalis.',
        22: 'Et ait Samuel: Numquid vult Dominus holocausta et victimas, et non potius ut obediatur voci eius? MELIOR est enim obedientia quam victimae: et auscultare magis quam offerre adipem arietum.',
        23: 'quoniam quasi peccatum ariolandi est, repugnare: et quasi scelus idololatriae, nolle acquiescere. Pro eo ergo quod abiecisti sermonem Domini, abiecit te Dominus ne sis rex.',
        24: 'Dixitque Saul ad Samuelem: Peccavi, quia praevaricatus sum sermonem Domini, et verba tua, timens populum, et obediens voci eorum.',
        25: 'Sed nunc porta, quaeso, peccatum meum, et revertere mecum, ut adorem Dominum.',
        26: 'Et ait Samuel ad Saul: Non revertar tecum, quia proiecisti sermonem Domini, et proiecit te Dominus ne sis rex super Israel.',
        27: 'Et conversus est Samuel ut abiret: ille autem apprehendit summitatem pallii eius, quae et scissa est.',
        28: 'Et ait ad eum Samuel: Scidit Dominus regnum Israel a te hodie, et tradidit illud proximo tuo meliori te.',
        29: 'Porro Triumphator in Israel non parcet, et poenitudine non flectetur: neque enim homo est ut agat poenitentiam.',
        30: 'At ille ait: Peccavi: sed nunc honora me coram senioribus populi mei, et coram Israel, et revertere mecum, ut adorem Dominum Deum tuum.',
        31: 'Reversus ergo Samuel secutus est Saulem: et adoravit Saul Dominum.',
        32: 'Dixitque Samuel: Adducite ad me Agag regem Amalec. Et oblatus est ei Agag pinguissimus, et tremens. Et dixit Samuel Agag: Siccine separat amara mors?',
        33: 'Et ait: Sicut fecit absque liberis mulieres gladius tuus, sic absque liberis erit inter mulieres mater tua. Et in frustra concidit eum Samuel coram Domino in Galgalis.',
        34: 'Abiit autem Samuel in Ramatha: Saul vero ascendit in domum suam in Gabaa',
        35: 'Et non vidit Samuel ultra Saul usque ad diem mortis suae: verumtamen lugebat Samuel Saulem, quoniam Dominum poenitebat quod constituisset eum regem super Israel.',
    },
    16: {
        1: 'Dixitque Dominus ad Samuelem: Usquequo tu luges Saul, cum ego proiecerim eum ne regnet super Israel? imple cornu tuum oleo, et veni, ut mittam te ad Isai Bethlehemitem: providi enim in filiis eius mihi regem.',
        2: 'Et ait Samuel: Quo modo vadam? audiet enim Saul, et interficiet me. Et ait Dominus: Vitulum de armento tolles in manu tua, et dices: Ad immolandum Domino veni.',
        3: 'Et vocabis Isai ad victimam, et ego ostendam tibi quid facias, et unges quemcumque monstravero tibi.',
        4: 'Fecit ergo Samuel, sicut locutus est ei Dominus. Venitque in Bethlehem, et admirati sunt seniores civitatis, occurrentes ei, dixeruntque: Pacificusne est ingressus tuus?',
        5: 'Et ait: Pacificus: ad immolandum Domino veni, sanctificamini, et venite mecum ut immolem. Sanctificavit ergo Isai et filios eius, et vocavit eos ad sacrificium.',
        6: 'Cumque ingressi essent, vidit Eliab, et ait: Num coram Domino est Christus eius?',
        7: 'Et dixit Dominus ad Samuelem: Ne respicias vultum eius, neque altitudinem staturae eius: quoniam abieci eum, nec iuxta intuitum hominis ego iudico: homo enim videt ea quae apparent, Dominus autem intuetur cor.',
        8: 'Et vocavit Isai Abinadab, et adduxit eum coram Samuele. Qui dixit: Nec hunc elegit Dominus.',
        9: 'Adduxit autem Isai Samma, de quo ait: Etiam hunc non elegit Dominus.',
        10: 'Adduxit itaque Isai septem filios suos coram Samuele: et ait Samuel ad Isai: Non elegit Dominus ex istis.',
        11: 'Dixitque Samuel ad Isai: Numquid iam completi sunt filii? Qui respondit: Adhuc reliquus est parvulus, et pascit oves. Et ait Samuel ad Isai: Mitte, et adduc eum: nec enim discumbemus prius quam huc ille veniat.',
        12: 'Misit ergo, et adduxit eum. Erat autem rufus, et pulcher aspectu, decoraque facie. et ait Dominus: Surge, et unge eum, ipse est enim.',
        13: 'Tulit ergo Samuel cornu olei, et unxit eum in medio fratrum eius: et directus est Spiritus Domini a die illa in David, et deinceps: surgensque Samuel abiit in Ramatha.',
        14: 'Spiritus autem Domini recessit a Saul et exagitabat eum spiritus nequam, a Domino.',
        15: 'Dixeruntque servi Saul ad eum: Ecce spiritus Dei malus exagitat te.',
        16: 'Iubeat dominus noster, et servi tui, qui coram te sunt, quaerent hominem scientem psallere cithara, ut quando arripuerit te spiritus Domini malus, psallat manu sua, et levius feras.',
        17: 'Et ait Saul ad servos suos: Providete ergo mihi aliquem bene psallentem, et adducite eum ad me.',
        18: 'Et respondens unus de pueris, ait: Ecce vidi filium Isai Bethlehemitem scientem psallere, et fortissimum robore, et virum bellicosum, et prudentem in verbis, et virum pulchrum: et Dominus est cum eo.',
        19: 'Misit ergo Saul nuncios ad Isai, dicens: Mitte ad me David filium tuum, qui est in pascuis.',
        20: 'Tulit itaque Isai asinum plenum panibus, et lagenam vini, et hoedum de capris unum, et misit per manum David filii sui Sauli.',
        21: 'Et venit David ad Saul, et stetit coram eo: at ille dilexit eum nimis, et factus est eius armiger.',
        22: 'Misitque Saul ad Isai, dicens: Stet David in conspectu meo: invenit enim gratiam in oculis meis.',
        23: 'Igitur quandocumque spiritus Domini malus arripiebat Saul, David tollebat citharam, et percutiebat manu sua, et refocillabatur Saul, et levius habebat. recedebat enim ab eo spiritus malus.',
    },
    17: {
        1: 'Congregantes autem Philisthiim agmina sua in praelium, convenerunt in Socho Iudae: et castrametati sunt inter Socho et Azeca in finibus Dommim.',
        2: 'Porro Saul et filii Israel congregati venerunt in Vallem terebinthi, et direxerunt aciem ad pugnandum contra Philisthiim.',
        3: 'Et Philisthiim stabant super montem ex parte hac, et Israel stabat supra montem ex altera parte: vallisque erat inter eos.',
        4: 'Et egressus est vir spurius de castris Philisthinorum nomine Goliath, de Geth, altitudinis sex cubitorum et palmi:',
        5: 'et cassis aerea super caput eius, et lorica hamata induebatur. porro pondus loricae eius, quinque millia siclorum aeris erat:',
        6: 'et ocreas aereas habebat in cruribus: et clypeus aereus tegebat humeros eius.',
        7: 'hastile autem hastae eius erat quasi liciatorium texentium. ipsum autem ferrum hastae eius sexcentos siclos habebat ferri: et armiger eius antecedebat eum.',
        8: 'Stansque clamabat adversum phalangas Israel, et dicebat eis: Quare venistis parati ad praelium? Numquid ego non sum Philisthaeus, et vos servi Saul? Eligite ex vobis virum, et descendat ad singulare certamen.',
        9: 'si quiverit pugnare mecum, et percusserit me, erimus vobis servi: si autem ego praevaluero, et percussero eum, vos servi eritis, et servietis nobis.',
        10: 'Et aiebat Philisthaeus: Ego exprobravi agminibus Israel hodie: Date mihi virum, et ineat mecum singulare certamen.',
        11: 'Audiens autem Saul, et omnes Israelitae sermones Philisthaei huiuscemodi, stupebant, et metuebant nimis.',
        12: 'David autem erat filius viri Ephrathaei, de quo supra dictum est, de Bethlehem Iuda, cui nomen erat Isai, qui habebat octo filios, et erat vir in diebus Saul senex, et grandaevus inter viros.',
        13: 'Abierunt autem tres filii eius maiores post Saul in praelium: et nomina trium filiorum eius, qui perrexerunt ad bellum, Eliab primogenitus, et secundus Abinadab, tertius quoque Samma.',
        14: 'David autem erat minimus. Tribus ergo maioribus secutis Saulem,',
        15: 'abiit David, et reversus est a Saul, ut pasceret gregem patris sui in Bethlehem.',
        16: 'Procedebat vero Philisthaeus mane et vespere, et stabat quadraginta diebus.',
        17: 'Dixit autem Isai ad David filium suum: Accipe fratribus tuis ephi polentae, et decem panes istos, et curre in castra ad fratres tuos,',
        18: 'et decem formellas casei has deferes ad tribunum: et fratres tuos visitabis, si recte agant: et cum quibus ordinati sunt, disce.',
        19: 'Saul autem, et illi, et omnes filii Israel, in Valle terebinthi pugnabant adversum Philisthiim.',
        20: 'Surrexit itaque David mane, et commendavit gregem custodi: et onustus abiit, sicut praeceperat ei Isai. Et venit ad locum Magala, et ad exercitum, qui egressus ad pugnam vociferatus erat in certamine.',
        21: 'Direxerat enim aciem Israel, sed et Philisthiim ex adverso fuerant praeparati.',
        22: 'Derelinquens ergo David vasa, quae attulerat, sub manu custodis ad sarcinas, cucurrit ad locum certaminis, et interrogabat si omnia recte agerentur erga fratres suos.',
        23: 'Cumque adhuc ille loqueretur eis, apparuit vir ille spurius ascendens, Goliath nomine, Philisthaeus, de Geth, de castris Philisthinorum: et loquente eo haec eadem verba audivit David.',
        24: 'Omnes autem Israelitae, cum vidissent virum, fugerunt a facie eius, timentes eum valde.',
        25: 'Et dixit unus quispiam de Israel: Num vidistis virum hunc, qui ascendit? ad exprobrandum enim Israeli ascendit. Virum ergo, qui percusserit eum, ditabit rex divitiis magnis, et filiam suam dabit ei, et domum patris eius faciet absque tributo in Israel.',
        26: 'Et ait David ad viros, qui stabant secum, dicens: Quid dabitur viro, qui percusserit Philisthaeum hunc, et tulerit opprobrium de Israel? quis enim est hic Philisthaeus incircumcisus, qui exprobravit acies Dei viventis?',
        27: 'Referebat autem ei populus eumdem sermonem, dicens: Haec dabuntur viro, qui percusserit eum.',
        28: 'Quod cum audisset Eliab frater eius maior, loquente eo cum aliis, iratus est contra David, et ait: Quare venisti, et quare dereliquisti pauculas oves illas in deserto? ego novi superbiam tuam, et nequitiam cordis tui: quia ut videres praelium, descendisti.',
        29: 'Et dixit David: Quid feci? numquid non verbum est?',
        30: 'Et declinavit paululum ab eo ad alium: dixitque eundem sermonem. Et respondit ei populus verbum sicut prius.',
        31: 'Audita sunt autem verba, quae locutus est David, et annunciata in conspectu Saul.',
        32: 'Ad quem cum fuisset adductus, locutus est ei: Non concidat cor cuiusquam in eo: ego servus tuus vadam, et pugnabo adversus Philisthaeum.',
        33: 'Et ait Saul ad David: Non vales resistere Philisthaeo isti, nec pugnare adversus eum: quia puer es, hic autem vir bellator est ab adolescentia sua.',
        34: 'Dixitque David ad Saul: Pascebat servus tuus patris sui gregem, et veniebat leo, vel ursus, et tollebat arietem de medio gregis:',
        35: 'et persequebar eos, et percutiebam, eruebamque de ore eorum: et illi consurgebant adversum me, et apprehendebam mentum eorum, et suffocabam, interficiebamque eos.',
        36: 'Nam et leonem, et ursum interfeci ego servus tuus: erit igitur et Philisthaeus hic incircumcisus, quasi unus ex eis. Nunc vadam, et auferam opprobrium populi: quoniam quis est iste Philisthaeus incircumcisus, qui ausus est maledicere exercitui Dei viventis?',
        37: 'Et ait David: Dominus qui eripuit me de manu leonis, et de manu ursi, ipse me liberabit de manu Philisthaei huius. Dixit autem Saul ad David: Vade, et Dominus tecum sit.',
        38: 'Et induit Saul David vestimentis suis, et imposuit galeam aeream super caput eius, et vestivit eum lorica.',
        39: 'Accinctus ergo David gladio eius super vestem suam, coepit tentare si armatus posset incedere: non enim habebat consuetudinem. Dixitque David ad Saul: Non possum sic incedere, quia non usum habeo. Et deposuit ea,',
        40: 'et tulit baculum suum, quem semper habebat in manibus: et elegit sibi quinque limpidissimos lapides de torrente, et misit eos in peram pastoralem, quam habebat secum, et fundam manu tulit: et processit adversum Philisthaeum.',
        41: 'ibat autem Philisthaeus incedens, et appropinquans adversum David, et armiger eius ante eum.',
        42: 'Cumque inspexisset Philisthaeus, et vidisset David, despexit eum. Erat autem adolescens: rufus, et pulcher aspectu.',
        43: 'Et dixit Philisthaeus ad David: Numquid ego canis sum, quod tu venis ad me cum baculo? Et maledixit Philisthaeus David in diis suis:',
        44: 'dixitque ad David: Veni ad me, et dabo carnes tuas volatilibus caeli et bestiis terrae.',
        45: 'Dixit autem David ad Philisthaeum: Tu venis ad me cum gladio, et hasta, et clypeo: ego autem venio ad te in nomine Domini exercituum, Dei agminum Israel, quibus exprobrasti',
        46: 'hodie, et dabit te Dominus in manu mea, et percutiam te, et auferam caput tuum a te: et dabo cadavera castrorum Philisthiim hodie volatilibus caeli, et bestiis terrae: ut sciat omnis terra quia est Deus in Israel.',
        47: 'Et noverit universa ecclesia haec, quia non in gladio, nec in hasta salvat Dominus: ipsius enim est bellum, et tradet vos in manus nostras.',
        48: 'Cum ergo surrexisset Philisthaeus, et veniret, et appropinquaret contra David, festinavit David, et cucurrit ad pugnam ex adverso Philisthaei.',
        49: 'Et misit manum suam in peram, tulitque unum lapidem, et funda iecit, et circumducens percussit Philisthaeum in fronte: et infixus est lapis in fronte eius, et cecidit in faciem suam super terram.',
        50: 'Praevaluitque David adversum Philisthaeum in funda et lapide, percussumque Philisthaeum interfecit. Cumque gladium non haberet in manu David,',
        51: 'cucurrit, et stetit super Philisthaeum, et tulit gladium eius, et eduxit eum de vagina sua: et interfecit eum, praeciditque caput eius. Videntes autem Philisthiim, quod mortuus esset fortissimus eorum, fugerunt.',
        52: 'Et consurgentes viri Israel et Iuda vociferati sunt, et persecuti sunt Philisthaeos usque dum venirent in vallem, et usque ad portas Accaron, cecideruntque vulnerati de Philisthiim in via Saraim, usque ad Geth, et usque ad Accaron.',
        53: 'Et revertentes filii Israel postquam persecuti fuerant Philisthaeos, invaserunt castra eorum.',
        54: 'Assumens autem David caput Philisthaei, attulit illud in Ierusalem: arma vero eius posuit in tabernaculo suo.',
        55: 'Eo autem tempore, quo viderat Saul David egredientem contra Philisthaeum, ait ad Abner principem militiae: De qua stirpe descendit hic adolescens? Dixitque Abner: Vivit anima tua, rex, si novi.',
        56: 'Et ait rex: Interroga tu, cuius filius sit iste puer.',
        57: 'Cumque regressus esset David, percusso Philisthaeo, tulit eum Abner, et introduxit coram Saule, caput Philisthaei habentem in manu.',
        58: 'Et ait ad eum Saul: De qua progenie es o adolescens? Dixitque David: Filius servi tui Isai Bethlehemitae ego sum.',
    },
    18: {
        1: 'Et factum est cum complesset loqui ad Saul: anima Ionathae conglutinata est animae David, et dilexit eum Ionathas quasi animam suam.',
        2: 'Tulitque eum Saul in die illa, et non concessit ei ut reverteretur in domum patris sui.',
        3: 'Inierunt autem David et Ionathas foedus: diligebat enim eum quasi animam suam.',
        4: 'Nam expoliavit se Ionathas tunica, qua erat indutus, et dedit eam David, et reliqua vestimenta sua usque ad gladium et arcum suum, et usque ad balteum.',
        5: 'Egrediebatur quoque David ad omnia quaecumque misisset eum Saul, et prudenter se agebat: posuitque eum Saul super viros belli, et acceptus erat in oculis universi populi, maximeque in conspectu famulorum Saul.',
        6: 'Porro cum reverteretur percusso Philisthaeo David, et ferret caput eius in Ierusalem egressae sunt mulieres de universis urbibus Israel, cantantes, chorosque ducentes in occursum Saul regis, in tympanis laetitiae, et in sistris.',
        7: 'Et praecinebant mulieres ludentes, atque dicentes: Percussit Saul mille, et David decem millia.',
        8: 'Iratus est autem Saul nimis, et displicuit in oculis eius sermo iste: dixitque: Dederunt David decem millia, et mihi mille dederunt: quid ei superest, nisi solum regnum?',
        9: 'Non rectis ergo oculis Saul aspiciebat David a die illa, et deinceps.',
        10: 'Post diem autem alteram, invasit spiritus Dei malus Saul, et prophetabat in medio domus suae: David autem psallebat manu sua, sicut per singulos dies. tenebatque Saul lanceam,',
        11: 'et misit eam, putans quod configere posset David cum pariete: et declinavit David a facie eius secundo.',
        12: 'Et timuit Saul David, eo quod Dominus esset cum eo, et a se recessisset.',
        13: 'Amovit ergo eum Saul a se, et fecit eum tribunum super mille viros: et egrediebatur, et intrabat in conspectu populi.',
        14: 'In omnibus quoque viis suis David prudenter agebat, et Dominus erat cum eo.',
        15: 'Vidit itaque Saul quod prudens esset nimis, et coepit cavere eum.',
        16: 'Omnis autem Israel et Iuda diligebat David: ipse enim ingrediebatur et egrediebatur ante eos.',
        17: 'Dixitque Saul ad David: Ecce filia mea maior Merob, ipsam dabo tibi uxorem: tantummodo esto vir fortis, et praeliare bella Domini. Saul autem reputabat, dicens: Non sit manus mea in eo, sed sit super eum manus Philisthinorum.',
        18: 'Ait autem David ad Saul: Quis ego sum, aut quae est vita mea, aut cognatio patris mei in Israel, ut fiam gener regis?',
        19: 'Factum est autem tempus cum deberet dari Merob filia Saul David, data est Hadrieli Molathitae uxor.',
        20: 'Dilexit autem David Michol filiam Saul alteram. Et nunciatum est Saul, et placuit ei.',
        21: 'Dixitque Saul: Dabo eam illi, ut fiat ei in scandalum, et sit super eum manus Philisthinorum. Dixitque Saul ad David: In duabus rebus gener meus eris hodie.',
        22: 'Et mandavit Saul servis suis: Loquimini ad David clam me, dicentes: Ecce places regi, et omnes servi eius diligunt te. Nunc ergo esto gener regis.',
        23: 'Et locuti sunt servi Saul in auribus David omnia verba haec. Et ait David: Num parum videtur vobis, generum esse regis? Ego autem sum vir pauper et tenuis.',
        24: 'Et renunciaverunt servi Saul, dicentes: Huiuscemodi verba locutus est David.',
        25: 'Dixit autem Saul: Sic loquimini ad David: Non habet rex sponsalia necesse, nisi tantum centum praeputia Philisthinorum, ut fiat ultio de inimicis regis. Porro Saul cogitabat tradere David in manus Philisthinorum.',
        26: 'Cumque renunciassent servi eius David verba, quae dixerat Saul, placuit sermo in oculis David, ut fieret gener regis.',
        27: 'Et post paucos dies surgens David, abiit cum viris, qui sub eo erant. Et percussit ex Philisthiim ducentos viros, et attulit eorum praeputia, et annumeravit ea regi, ut esset gener eius. Dedit itaque Saul ei Michol filiam suam uxorem.',
        28: 'Et vidit Saul, et intellexit quod Dominus esset cum David. Michol autem filia Saul diligebat eum.',
        29: 'Et Saul magis coepit timere David: factusque est Saul inimicus David cunctis diebus.',
        30: 'Et egressi sunt principes Philisthinorum. a principio autem egressionis eorum, prudentius se gerebat David quam omnes servi Saul, et celebre factum est nomen eius nimis.',
    },
    19: {
        1: 'Locutus est autem Saul ad Ionathan filium suum, et ad omnes servos suos, ut occiderent David. Porro Ionathas filius Saul diligebat David valde.',
        2: 'Et indicavit Ionathas David, dicens: Quaerit Saul pater meus occidere te: quapropter observa te, quaeso, mane, et manebis clam, et absconderis.',
        3: 'Ego autem egrediens stabo iuxta patrem meum, in agro ubicumque fuerit: et ego loquar de te ad patrem meum: et quodcumque videro, nunciabo tibi.',
        4: 'Locutus est ergo Ionathas de David bona ad Saul patrem suum: dixitque ad eum: Ne pecces rex in servum tuum David, quia non peccavit tibi, et opera eius bona sunt tibi valde.',
        5: 'Et posuit animam suam in manu sua, et percussit Philisthaeum, et fecit Dominus salutem magnam universo Israeli: vidisti, et laetatus es. Quare ergo peccas in sanguine innoxio, interficiens David, qui est absque culpa?',
        6: 'Quod cum audisset Saul, placatus voce Ionathae, iuravit: Vivit Dominus, quia non occidetur.',
        7: 'Vocavit itaque Ionathas David, et indicavit ei omnia verba haec: et introduxit Ionathas David ad Saul, et fuit ante eum, sicut fuerat heri et nudiustertius.',
        8: 'Motum est autem rursum bellum: et egressus David, pugnavit adversum Philisthiim: percussitque eos plaga magna, et fugerunt a facie eius.',
        9: 'Et factus est spiritus Domini malus in Saul. sedebat autem in domo sua, et tenebat lanceam: porro David psallebat manu sua.',
        10: 'Nisusque est Saul configere David lancea in pariete, et declinavit David a facie Saul: lancea autem casso vulnere perlata est in parietem, et David fugit, et salvatus est nocte illa.',
        11: 'Misit ergo Saul satellites suos in domum David, ut custodirent eum, et interficeretur mane. Quod cum annunciasset David Michol uxor sua, dicens: Nisi salvaveris te nocte hac, cras morieris:',
        12: 'deposuit eum per fenestram. porro ille abiit et aufugit, atque salvatus est.',
        13: 'Tulit autem Michol statuam, et posuit eam super lectum, et pellem pilosam caprarum posuit ad caput eius, et operuit eam vestimentis.',
        14: 'Misit autem Saul apparitores, qui raperent David: et responsum est quod aegrotaret.',
        15: 'Rursumque misit Saul nuncios ut viderent David, dicens: Afferte eum ad me in lecto, ut occidatur.',
        16: 'Cumque venissent nuncii, inventum est simulacrum super lectum, et pellis caprarum ad caput eius.',
        17: 'Dixitque Saul ad Michol: Quare sic illusisti mihi, et dimisisti inimicum meum ut fugeret? Et respondit Michol ad Saul: Quia ipse locutus est mihi: Dimitte me, alioquin interficiam te.',
        18: 'David autem fugiens salvatus est, et venit ad Samuel in Ramatha, et nunciavit ei omnia quae fecerat sibi Saul: et abierunt ipse et Samuel, et morati sunt in Naioth.',
        19: 'Nunciatum est autem Sauli a dicentibus: Ecce David in Naioth in Ramatha.',
        20: 'Misit ergo Saul lictores, ut raperent David: qui cum vidissent cuneum prophetarum vaticinantium, et Samuelem stantem super eos, factus est etiam Spiritus Domini in illis, et prophetare coeperunt etiam ipsi.',
        21: 'Quod cum nunciatum esset Sauli, misit et alios nuncios: prophetaverunt autem et illi. Et rursum misit Saul tertios nuncios: qui et ipsi prophetaverunt. Et iratus iracundia Saul,',
        22: 'abiit etiam ipse in Ramatha, et venit usque ad cisternam magnam, quae est in Socho, et interrogavit, et dixit: In quo loco sunt Samuel et David? Dictumque est ei: Ecce in Naioth sunt in Ramatha.',
        23: 'Et abiit in Naioth in Ramatha, et factus est etiam super eum Spiritus Domini, et ambulabat ingrediens, et prophetabat usque dum veniret in Naioth in Ramatha.',
        24: 'Et expoliavit etiam ipse se vestimentis suis, et prophetavit cum ceteris coram Samuele, et cecinit nudus tota die illa et nocte. Unde et exivit proverbium: Num et Saul inter prophetas?',
    },
    20: {
        1: 'Fugit autem David de Naioth, quae est in Ramatha, veniensque locutus est coram Ionatha: Quid feci? quae est iniquitas mea, et quod peccatum meum in patrem tuum, quia quaerit animam meam?',
        2: 'Qui dixit ei: Absit, non morieris: neque enim faciet pater meus quidquam grande vel parvum, nisi prius indicaverit mihi: hunc ergo celavit me pater meus sermonem tantummodo? nequaquam erit istud.',
        3: 'Et iuravit rursum Davidi. Et ille ait: Scit profecto pater tuus quia inveni gratiam in oculis tuis, et dicet: Nesciat hoc Ionathas, ne forte tristetur. Quinimmo vivit Dominus, et vivit anima tua, quia uno tantum (ut ita dicam) gradu, ego morsque dividimur.',
        4: 'Et ait Ionathas ad David: Quodcumque dixerit mihi anima tua, faciam tibi.',
        5: 'Dixit autem David ad Ionathan: Ecce calendae sunt crastino, et ego ex more sedere soleo iuxta regem ad vescendum: dimitte ergo me ut abscondar in agro usque ad vesperam diei tertiae.',
        6: 'Si respiciens requisierit me pater tuus, respondebis ei: Rogavit me David, ut iret celeriter in Bethlehem civitatem suam: quia victimae sollemnes ibi sunt universis contribulibus suis.',
        7: 'Si dixerit, Bene: pax erit servo tuo. si autem fuerit iratus, scito quia completa est malitia eius.',
        8: 'Fac ergo misericordiam in servum tuum: quia foedus Domini me famulum tuum tecum inire fecisti. si autem est iniquitas aliqua in me, tu me interfice, et ad patrem tuum ne introducas me.',
        9: 'Et ait Ionathas: Absit hoc a me: neque enim fieri potest, ut si certe cognovero completam esse patris mei malitiam contra te, non annunciem tibi.',
        10: 'Responditque David ad Ionathan: Quis renunciabit mihi, si quid forte responderit tibi pater tuus dure de me?',
        11: 'Et ait Ionathas ad David: Veni, et egrediamur foras in agrum. Cumque exissent ambo in agrum,',
        12: 'ait Ionathas ad David: Domine Deus Israel, si investigavero sententiam patris mei crastino vel perendie: et aliquid boni fuerit super David, et non statim misero ad te, et notum tibi fecero,',
        13: 'haec faciat Dominus Ionathae, et haec addat. Si autem perseveraverit patris mei malitia adversum te, revelabo aurem tuam, et dimittam te, ut vadas in pace, et sit Dominus tecum, sicut fuit cum patre meo.',
        14: 'Et si vixero, facies mihi misericordiam Domini: si vero mortuus fuero,',
        15: 'non auferes misericordiam tuam a domo mea usque in sempiternum, quando eradicaverit Dominus inimicos David, unumquemque de terra: auferat Ionathan de domo sua, et requirat Dominus de manu inimicorum David.',
        16: 'Pepigit ergo Ionathas foedus cum domo David: et requisivit Dominus de manu inimicorum David.',
        17: 'Et addidit Ionathas deierare David, eo quod diligeret illum: sicut enim animam suam, ita diligebat eum.',
        18: 'Dixitque ad eum Ionathas: Cras calendae sunt, et requireris:',
        19: 'requiretur enim sessio tua usque perendie. Descendes ergo festinus, et venies in locum ubi celandus es in die qua operari licet, et sedebis iuxta lapidem, cui nomen est Ezel.',
        20: 'Et ego tres sagittas mittam iuxta eum, et iaciam quasi exercens me ad signum.',
        21: 'Mittam quoque et puerum, dicens ei: Vade, et affer mihi sagittas.',
        22: 'Si dixero puero: Ecce sagittae intra te sunt, tolle eas: tu veni ad me, quia pax tibi est, et nihil est mali, vivit Dominus. Si autem sic locutus fuero puero: Ecce sagittae citra te sunt: vade in pace, quia dimisit te Dominus.',
        23: 'De verbo autem quod locuti sumus ego et tu, sit Dominus inter me et te usque in sempiternum.',
        24: 'Absconditus est ergo David in agro, et venerunt calendae, et sedit rex ad comedendum panem.',
        25: 'Cumque sedisset rex super cathedram suam (secundum consuetudinem) quae erat iuxta parietem, surrexit Ionathas, et sedit Abner ex latere Saul, vacuusque apparuit locus David.',
        26: 'Et non est locutus Saul quidquam in die illa: cogitabat enim quod forte evenisset ei, ut non esset mundus, nec purificatus.',
        27: 'Cumque illuxisset dies secunda post calendas, rursus apparuit vacuus locus David. Dixitque Saul ad Ionathan filium suum: Cur non venit filius Isai nec heri, nec hodie ad vescendum?',
        28: 'Responditque Ionathas Sauli: Rogavit me obnixe, ut iret in Bethlehem,',
        29: 'et ait: Dimitte me, quoniam sacrificium sollemne est in civitate, unus de fratribus meis accersivit me: nunc ergo si inveni gratiam in oculis tuis, vadam cito, et videbo fratres meos. Ob hanc causam non venit ad mensam regis.',
        30: 'Iratus autem Saul adversum Ionathan, dixit ei: Fili mulieris virum ultro rapientis, numquid ignoro quia diligis filium Isai in confusionem tuam, et in confusionem ignominiosae matris tuae?',
        31: 'Omnibus enim diebus, quibus filius Isai vixerit super terram, non stabilieris tu, neque regnum tuum. Itaque iam nunc mitte, et adduc eum ad me: quia filius mortis est.',
        32: 'Respondens autem Ionathas Sauli patri suo, ait: Quare morietur? quid fecit?',
        33: 'Et arripuit Saul lanceam ut percuteret eum. Et intellexit Ionathas quod definitum esset a patre suo, ut interficeret David.',
        34: 'Surrexit ergo Ionathas a mensa in ira furoris, et non comedit in die calendarum secunda panem. Contristatus est enim super David, eo quod confudisset eum pater suus.',
        35: 'Cumque illuxisset mane, venit Ionathas in agrum iuxta placitum David, et puer parvulus cum eo,',
        36: 'et ait ad puerum suum: Vade, et affer mihi sagittas, quas ego iacio. Cumque puer cucurrisset, iecit aliam sagittam trans puerum.',
        37: 'Venit itaque puer ad locum iaculi, quod miserat Ionathas: et clamavit Ionathas post tergum pueri, et ait: Ecce ibi est sagitta porro ultra te.',
        38: 'Clamavitque iterum Ionathas post tergum pueri, dicens: Festina velociter, ne steteris. Collegit autem puer Ionathae sagittas, et attulit ad dominum suum:',
        39: 'et quid ageretur, penitus ignorabat: tantummodo enim Ionathas et David rem noverant.',
        40: 'Dedit ergo Ionathas arma sua puero, et dixit ei: Vade, et defer in civitatem.',
        41: 'Cumque abiisset puer, surrexit David de loco, qui vergebat ad Austrum, et cadens pronus in terram, adoravit tertio: et osculantes se alterutrum, fleverunt pariter, David autem amplius.',
        42: 'Dixit ergo Ionathas ad David: Vade in pace: quaecumque iuravimus ambo in nomine Domini, dicentes: Dominus sit inter me et te, et inter semen tuum et semen meum usque in sempiternum.',
        43: 'Et surrexit David, et abiit: sed et Ionathas ingressus est civitatem.',
    },
    21: {
        1: 'Venit autem David in Nobe ad Achimelech sacerdotem: et obstupuit Achimelech, eo quod venisset David. Et dixit ei: Quare tu solus, et nullus est tecum?',
        2: 'Et ait David ad Achimelech sacerdotem: Rex praecepit mihi sermonem, et dixit: Nemo sciat rem, propter quam missus es a me, et cuiusmodi praecepta tibi dederim: nam et pueris condixi in illum et illum locum.',
        3: 'Nunc ergo siquid habes ad manum, vel quinque panes, da mihi, aut quidquid inveneris.',
        4: 'Et respondens sacerdos ad David, ait illi: Non habeo laicos panes ad manum, sed tantum panem sanctum: si mundi sunt pueri, maxime a mulieribus?',
        5: 'Et respondit David sacerdoti, et dixit ei: Equidem, si de mulieribus agitur: continuimus nos ab heri et nudiustertius, quando egrediebamur, et fuerunt vasa puerorum sancta. porro via haec polluta est, sed et ipsa hodie sanctificabitur in vasis.',
        6: 'Dedit ergo ei sacerdos sanctificatum panem. neque enim erat ibi panis, nisi tantum panes propositionis, qui sublati fuerant a facie Domini, ut ponerentur panes calidi.',
        7: 'Erat autem ibi vir quidam de servis Saul, in die illa, intus in tabernaculo Domini: et nomen eius Doeg Idumaeus, potentissimus pastorum Saul.',
        8: 'Dixit autem David ad Achimelech: Si habes hic ad manum hastam, aut gladium? quia gladium meum, et arma mea non tuli mecum. sermo enim regis urgebat.',
        9: 'Et dixit sacerdos: Ecce hic gladius Goliath Philisthaei, quem percussisti in Valle terebinthi, est involutus pallio post ephod: si istum vis tollere, tolle. neque enim hic est alius absque eo. Et ait David: Non est huic alter similis, da mihi eum.',
        10: 'Surrexit itaque David, et fugit in die illa a facie Saul: et venit ad Achis regem Geth:',
        11: 'dixeruntque servi Achis ad eum cum vidissent David: Numquid non iste est David rex terrae? nonne huic cantabant per choros, dicentes: Percussit Saul mille, et David decem millia?',
        12: 'Posuit autem David sermones istos in corde suo, et extimuit valde a facie Achis regis Geth.',
        13: 'Et immutavit os suum coram eis, et collabebatur inter manus eorum: et impingebat in ostia portae, defluebantque salivae eius in barbam.',
        14: 'Et ait Achis ad servos suos: Vidistis hominem insanum: quare adduxistis eum ad me?',
        15: 'An desunt nobis furiosi, quod introduxistis istum, ut fureret me praesente? hiccine ingredietur domum meam?',
    },
    22: {
        1: 'Abiit ergo David inde, et fugit in speluncam Odollam. Quod cum audissent fratres eius, et omnis domus patris eius, descenderunt ad eum illuc.',
        2: 'Et convenerunt ad eum omnes, qui erant in angustia constituti, et oppressi aere alieno, et amaro animo: et factus est eorum princeps, fueruntque cum eo quasi quadringenti viri.',
        3: 'Et profectus est David inde in Maspha, quae est Moab: et dixit ad regem Moab: Maneat, oro, pater meus et mater mea vobiscum, donec sciam quid faciat mihi Deus.',
        4: 'Et reliquit eos ante faciem regis Moab: manseruntque apud eum cunctis diebus, quibus David fuit in praesidio.',
        5: 'Dixitque Gad propheta ad David: Noli manere in praesidio, proficiscere, et vade in Terram Iuda. Et profectus est David, et venit in saltum Haret.',
        6: 'Et audivit Saul quod apparuisset David, et viri qui erant cum eo. Saul autem cum maneret in Gabaa, et esset in nemore, quod est in Rama, hastam manu tenens, cunctique servi eius circumstarent eum,',
        7: 'ait ad servos suos qui assistebant ei: Audite me nunc filii Iemini: numquid omnibus vobis dabit filius Isai agros et vineas, et universos vos faciet tribunos, et centuriones:',
        8: 'quoniam coniurastis omnes adversum me, et non est qui mihi renunciet, maxime cum et filius meus foedus inierit cum filio Isai? Non est qui vicem meam doleat ex vobis, nec qui annunciet mihi: eo quod suscitaverit filius meus servum meum adversum me, insidiantem mihi usque hodie.',
        9: 'Respondens autem Doeg Idumaeus, qui assistebat, et erat primus inter servos Saul, Vidi, inquit, filium Isai in Nobe apud Achimelech filium Achitob sacerdotem.',
        10: 'Qui consuluit pro eo Dominum, et cibaria dedit ei: sed et gladium Goliath Philisthaei dedit illi.',
        11: 'Misit ergo rex ad accersendum Achimelech sacerdotem filium Achitob, et omnem domum patris eius, sacerdotum, qui erant in Nobe, qui universi venerunt ad regem.',
        12: 'Et ait Saul ad Achimelech: Audi fili Achitob. Qui respondit: Praesto sum Domine.',
        13: 'Dixitque ad eum Saul: Quare coniurastis adversum me, tu et filius Isai, et dedisti ei panes et gladium, et consuluisti pro eo Dominum, ut consurgeret adversum me, insidiator usque hodie permanens?',
        14: 'Respondensque Achimelech regi, ait: Et quis in omnibus servis tuis, sicut David fidelis, et gener regis, et pergens ad imperium tuum, et gloriosus in domo tua?',
        15: 'Num hodie coepi pro eo consulere Dominum? absit hoc a me: ne suspicetur rex adversus servum suum rem huiuscemodi, in universa domo patris mei: non enim scivit servus tuus quidquam super hoc negotio, vel modicum vel grande.',
        16: 'Dixitque rex: Morte morieris Achimelech, tu, et omnis domus patris tui.',
        17: 'Et ait rex emissariis qui circumstabant eum: Convertimini, et interficite sacerdotes Domini: nam manus eorum cum David est: scientes quod fugisset, et non indicaverunt mihi. Noluerunt autem servi regis extendere manus suas in sacerdotes Domini.',
        18: 'Et ait rex ad Doeg: Convertere tu, et irrue in sacerdotes. Conversusque Doeg Idumaeus, irruit in sacerdotes, et trucidavit in die illa octogintaquinque viros vestitos ephod lineo.',
        19: 'Nobe autem civitatem sacerdotum percussit in ore gladii, viros et mulieres, et parvulos, et lactentes, bovemque et asinum, et ovem in ore gladii.',
        20: 'Evadens autem unus filius Achimelech, filii Achitob, cuius nomen erat Abiathar, fugit ad David,',
        21: 'et annunciavit ei quod occidisset Saul sacerdotes Domini.',
        22: 'Et ait David ad Abiathar: Sciebam in die illa, quod cum ibi esset Doeg Idumaeus, proculdubio annunciaret Sauli: ego sum reus omnium animarum patris tui.',
        23: 'Mane mecum, ne timeas: si quis quaesierit animam meam, quaeret et animam tuam, mecumque servaberis.',
    },
    23: {
        1: 'Et annunciaverunt David, dicentes: Ecce Philisthiim oppugnant Ceilam, et diripiunt areas.',
        2: 'Consuluit ergo David Dominum, dicens: Num vadam, et percutiam Philisthaeos istos? Et ait Dominus ad David: Vade, et percuties Philisthaeos, et Ceilam salvabis.',
        3: 'Et dixerunt viri, qui erant cum David, ad eum: Ecce nos hic in Iudaea consistentes timemus: quanto magis si ierimus in Ceilam adversum agmina Philisthinorum?',
        4: 'Rursum ergo David consuluit Dominum. Qui respondens, ait ei: Surge, et vade in Ceilam: ego enim tradam Philisthaeos in manu tua.',
        5: 'Abiit ergo David, et viri eius in Ceilam, et pugnavit adversum Philisthaeos, et abegit iumenta eorum, et percussit eos plaga magna: et salvavit David habitatores Ceilae.',
        6: 'Porro eo tempore, quo fugiebat Abiathar filius Achimelech ad David in Ceilam, ephod secum habens descenderat.',
        7: 'Nunciatum est autem Sauli quod venisset David in Ceilam: et ait Saul: Tradidit eum Dominus in manus meas, conclususque est introgressus urbem, in qua portae et serae sunt.',
        8: 'Et praecepit Saul omni populo ut ad pugnam descenderet in Ceilam: et obsideret David, et viros eius.',
        9: 'Quod cum David rescisset quia praepararet ei Saul clam malum, dixit ad Abiathar sacerdotem: Applica ephod.',
        10: 'Et ait David: Domine Deus Israel, audivit famam servus tuus, quod disponat Saul venire in Ceilam, ut evertat urbem propter me:',
        11: 'Si tradent me viri Ceilae in manus eius? et si descendet Saul, sicut audivit servus tuus? Domine Deus Israel indica servo tuo. Et ait Dominus: Descendet.',
        12: 'Dixitque David: Si tradent me viri Ceilae, et viros qui sunt mecum, in manus Saul? et dixit Dominus: Tradent.',
        13: 'Surrexit ergo David et viri eius quasi sexcenti, et egressi de Ceila, huc atque illuc vagabantur incerti: nunciatumque est Sauli quod fugisset David de Ceila, et salvatus esset: quam ob rem dissimulavit exire.',
        14: 'Morabatur autem David in deserto in locis firmissimis, mansitque in monte solitudinis Ziph, in monte opaco: quaerebat eum tamen Saul cunctis diebus: et non tradidit eum Dominus in manus eius.',
        15: 'Et vidit David quod egressus esset Saul ut quaereret animam eius. Porro David erat in deserto Ziph in silva.',
        16: 'Et surrexit Ionathas filius Saul, et abiit ad David in silvam, et confortavit manus eius in Deo: dixitque ei:',
        17: 'Ne timeas: neque enim inveniet te manus Saul patris mei, et tu regnabis super Israel, et ego ero tibi secundus, sed et Saul pater meus scit hoc.',
        18: 'Percussit ergo uterque foedus coram Domino: mansitque David in silva: Ionathas autem reversus est in domum suam.',
        19: 'Ascenderunt autem Ziphaei ad Saul in Gabaa, dicentes: Nonne ecce David latitat apud nos in locis tutissimis silvae, in Colle Hachila, quae est ad dexteram deserti?',
        20: 'Nunc ergo, sicut desideravit anima tua ut descenderes, descende: nostrum autem erit ut tradamus eum in manus regis.',
        21: 'Dixitque Saul: Benedicti vos a Domino, quia doluistis vicem meam.',
        22: 'Abite ergo, oro, et diligentius praeparate, et curiosius agite, et considerate locum ubi sit pes eius, vel quis viderit eum ibi, recogitat enim de me, quod callide insidier ei.',
        23: 'Considerate et videte omnia latibula eius, in quibus absconditur: et revertimini ad me ad rem certam, ut vadam vobiscum. quod si etiam in terram se obstruxerit, perscrutabor eum in cunctis millibus Iuda.',
        24: 'At illi surgentes abierunt in Ziph ante Saul: David autem et viri eius erant in deserto Maon, in campestribus ad dexteram Iesimon.',
        25: 'Ivit ergo Saul et socii eius ad quaerendum eum: et nunciatum est David, statimque descendit ad petram, et versabatur in deserto Maon. quod cum audisset Saul, persecutus est David in deserto Maon.',
        26: 'Et ibat Saul ad latus montis ex parte una: David autem et viri eius erant in latere montis ex parte altera: porro David desperabat se posse evadere a facie Saul: itaque Saul, et viri eius in modum coronae cingebant David, et viros eius, ut caperent eos.',
        27: 'Et nuncius venit ad Saul, dicens: Festina, et veni, quoniam infuderunt se Philisthiim super terram.',
        28: 'Reversus est ergo Saul desistens persequi David, et perrexit in occursum Philisthinorum. propter hoc vocaverunt locum illum, Petram dividentem.',
    },
    24: {
        1: 'Ascendit ergo David inde: et habitavit in locis tutissimis Engaddi.',
        2: 'Cumque reversus esset Saul, postquam persecutus est Philisthaeos, nunciaverunt ei, dicentes: Ecce, David in deserto est Engaddi.',
        3: 'Assumens ergo Saul tria millia electorum virorum ex omni Israel, perrexit ad investigandum David et viros eius, etiam super abruptissimas petras, quae solis ibicibus perviae sunt.',
        4: 'Et venit ad caulas ovium, quae se offerebant vianti. eratque ibi spelunca, quam ingressus est Saul, ut purgaret ventrem: porro David et viri eius in interiore parte speluncae latebant.',
        5: 'Et dixerunt servi David ad eum: Ecce dies, de qua locutus est Dominus ad te: Ego tradam tibi inimicum tuum, ut facias ei sicut placuerit in oculis tuis. Surrexit ergo David, et praecidit oram chlamydis Saul silenter.',
        6: 'Post haec percussit cor suum David, eo quod abscidisset oram chlamydis Saul.',
        7: 'Dixitque ad viros suos: Propitius sit mihi Dominus, ne faciam hanc rem domino meo, christo Domini, ut mittam manum meam in eum, quia christus Domini est. Vivit dominus, quia nisi Dominus percusserit eum, aut dies eius venerit ut moriatur, aut descendens in proelium perierit, propitius mihi sit Dominus, ut non mittam manu meam in Christum Domini.',
        8: 'Et confregit David viros suos sermonibus, et non permisit eos ut consurgerent in Saul: porro Saul exurgens de spelunca, pergebat coepto itinere.',
        9: 'Surrexit autem David post eum: et egressus de spelunca, clamavit post tergum Saul, dicens: Domine mi rex. Et respexit Saul post se: et inclinans se David pronus in terram, adoravit,',
        10: 'dixitque ad Saul: Quare audis verba hominum loquentium, David quaerit malum adversum te?',
        11: 'Ecce hodie viderunt oculi tui quod tradiderit te Dominus in manu mea in spelunca: et cogitavi ut occiderem te, sed pepercit tibi oculus meus. dixi enim: Non extendam manum meam in dominum meum, quia christus Domini est.',
        12: 'Quin potius pater mi, vide, et cognosce oram chlamydis tuae in manu mea: quoniam cum praescinderem summitatem chlamydis tuae, nolui extendere manum meam in te. animadverte, et vide, quoniam non est in manu mea malum, neque iniquitas, neque peccavi in te: tu autem insidiaris animae meae ut auferas eam.',
        13: 'Iudicet Dominus inter me et te, et ulciscatur me Dominus ex te: manus autem mea non sit in te.',
        14: 'Sicut et in proverbio antiquo dicitur: AB IMPIIS egredietur impietas: manus ergo mea non sit in te.',
        15: 'Quem persequeris, rex Israel? quem persequeris? canem mortuum persequeris, et pulicem unum.',
        16: 'Sit Dominus iudex, et iudicet inter me et te: et videat, et iudicet causam meam, et eruat me de manu tua.',
        17: 'Cum autem complesset David loquens sermones huiuscemodi ad Saul, dixit Saul: Numquid vox haec tua est fili mi David? Et levavit Saul vocem suam, et flevit:',
        18: 'dixitque ad David: Iustior tu es quam ego: tu enim tribuisti mihi bona: ego autem reddidi tibi mala.',
        19: 'Et tu indicasti hodie quae feceris mihi bona: quomodo tradiderit me Dominus in manum tuam, et non occideris me.',
        20: 'Quis enim cum invenerit inimicum suum, dimittet eum in via bona? Sed Dominus reddat tibi vicissitudinem hanc pro eo quod hodie operatus es in me.',
        21: 'Et nunc quia scio quod certissime regnaturus sis, et habiturus in manu tua regnum Israel:',
        22: 'iura mihi in Domino, ne deleas semen meum post me, neque auferas nomen meum de domo patris mei.',
        23: 'Et iuravit David Sauli. Abiit ergo Saul in domum suam: et David, et viri eius ascenderunt ad tutiora loca.',
    },
    25: {
        1: 'Mortuus est autem Samuel, et congregatus est universus Israel, et planxerunt eum, et sepelierunt eum in domo sua in Ramatha. Consurgensque David descendit in desertum Pharan.',
        2: 'Erat autem vir quispiam in solitudine Maon, et possessio eius in Carmelo, et homo ille magnus nimis: erantque ei oves tria millia, et mille caprae: et accidit ut tonderetur grex eius in Carmelo.',
        3: 'Nomen autem viri illius erat Nabal: et nomen uxoris eius Abigail. eratque mulier illa prudentissima et speciosa: porro vir eius durus, et pessimus, et malitiosus: erat autem de genere Caleb.',
        4: 'Cum ergo audisset David in deserto quod tonderet Nabal gregem suum,',
        5: 'misit decem iuvenes, et dixit eis: Ascendite in Carmelum, et venietis ad Nabal, et salutabitis eum ex nomine meo pacifice.',
        6: 'Et dicetis: Sit fratribus meis, et tibi pax, et domui tuae pax, et omnibus, quaecumque habes, sit pax. Ex multis annis salvos faciens tuos, et omnia tua.',
        7: 'Audivi quod tonderent pastores tui, qui erant nobiscum in deserto: numquam eis molesti fuimus, nec aliquando defuit quidquam eis de grege, omni tempore quo fuerunt nobiscum in Carmelo.',
        8: 'Interroga pueros tuos, et indicabunt tibi. Nunc ergo inveniant pueri tui gratiam in oculis tuis: in die enim bona venimus. quodcumque invenerit manus tua, da servis tuis, et filio tuo David.',
        9: 'Cumque venissent pueri David, locuti sunt ad Nabal omnia verba haec ex nomine David: et siluerunt.',
        10: 'Respondens autem Nabal pueris David, ait: Quis est David? et quis est filius Isai? hodie increverunt servi qui fugiunt dominos suos.',
        11: 'Tollam ergo panes meos, et aquas meas, et carnes pecorum, quae occidi tonsoribus meis, et dabo viris quos nescio unde sint?',
        12: 'Regressi sunt itaque pueri David per viam suam, et reversi venerunt, et annunciaverunt ei omnia verba quae dixerat.',
        13: 'Tunc ait David pueris suis: Accingatur unusquisque gladio suo. Et accincti sunt singuli gladiis suis, accinctusque est et David ense suo: et secuti sunt David quasi quadringenti viri: porro ducenti remanserunt ad sarcinas.',
        14: 'Abigail autem uxori Nabal nunciavit unus de pueris suis, dicens: Ecce David misit nuncios de deserto, ut benedicerent domino nostro: et aversatus est eos.',
        15: 'homines isti, boni satis fuerant nobis, et non molesti: nec quidquam aliquando periit omni tempore, quo fuimus conversati cum eis in deserto:',
        16: 'pro muro erant nobis tam in nocte quam in die, omnibus diebus quibus pavimus apud eos greges.',
        17: 'Quam ob rem considera, et recogita quid facias: quoniam completa est malitia adversum virum tuum, et adversum domum tuam, et ipse est filius Belial, ita ut nemo possit ei loqui.',
        18: 'Festinavit igitur Abigail, et tulit ducentos panes, et duos utres vini, et quinque arietes coctos, et quinque sata polentae, et centum ligaturas uvae passae, et ducentas massas caricarum, et posuit super asinos:',
        19: 'dixitque pueris suis: Praecedite me: ecce, ego post tergum sequar vos: viro autem suo Nabal non indicavit.',
        20: 'Cum ergo ascendisset asinum, et descenderet ad radices montis, David et viri eius descendebant in occursum eius: quibus et illa occurrit.',
        21: 'Et ait David: Vere frustra servavi omnia quae huius erant in deserto, et non periit quidquam de cunctis quae ad eum pertinebant: et reddidit mihi malum pro bono.',
        22: 'Haec faciat Deus inimicis David, et haec addat, si reliquero de omnibus quae ad ipsum pertinent usque mane, mingentem ad parietem.',
        23: 'Cum autem vidisset Abigail David, festinavit, et descendit de asino, et procidit coram David super faciem suam, et adoravit super terram,',
        24: 'et cecidit ad pedes eius, et dixit: In me sit, domine mi, haec iniquitas: loquatur, obsecro, ancilla tua in auribus tuis: et audi verba famulae tuae.',
        25: 'Ne ponat, oro, dominus meus rex cor suum super virum istum iniquum Nabal: quoniam secundum nomen suum stultus est, et stultitia est cum eo: ego autem ancilla tua non vidi pueros tuos, domine mi, quos misisti.',
        26: 'Nunc ergo domine mi, vivit Dominus, et vivit anima tua, qui prohibuit te ne venires in sanguinem, et salvavit manum tuam tibi: et nunc fiant sicut Nabal inimici tui, et qui quaerunt domino meo malum.',
        27: 'Quapropter suscipe benedictionem hanc, quam attulit ancilla tua tibi domino meo: et da pueris qui sequuntur te dominum meum.',
        28: 'Aufer iniquitatem famulae tuae: faciens enim faciet Dominus tibi domino meo domum fidelem, quia praelia Domini, domine mi, tu praeliaris: malitia ergo non inveniatur in te omnibus diebus vitae tuae.',
        29: 'Si enim surrexerit aliquando homo persequens te, et quaerens animam tuam, erit anima domini mei custodita quasi in fasciculo viventium, apud Dominum Deum tuum: porro inimicorum tuorum anima rotabitur, quasi in impetu et circulo fundae.',
        30: 'Cum ergo fecerit Dominus tibi domino meo omnia quae locutus est bona de te, et constituerit te ducem super Israel,',
        31: 'non erit tibi hoc in singultum, et in scrupulum cordis domino meo, quod effuderis sanguinem innoxium, aut ipse te ultus fueris: et cum benefecerit Dominus domino meo, recordaberis ancillae tuae.',
        32: 'Et ait David ad Abigail: Benedictus Dominus Deus Israel, qui misit hodie te in occursum meum, et benedictum eloquium tuum,',
        33: 'et benedicta tu, quae prohibuisti me hodie ne irem ad sanguinem, et ulciscerer me manu mea.',
        34: 'Alioquin vivit Dominus Deus Israel qui prohibuit me ne malum facerem tibi: nisi cito venisses in occursum mihi, non remansisset Nabal usque ad lucem matutinam, mingens ad parietem.',
        35: 'Suscepit ergo David de manu eius omnia quae attulerat ei, dixitque ei: Vade pacifice in domum tuam, ecce audivi vocem tuam, et honoravi faciem tuam.',
        36: 'Venit autem Abigail ad Nabal: et ecce erat ei convivium in domo eius, quasi convivium regis, et cor Nabal iucundum: erat enim ebrius nimis: et non indicavit ei verbum pusillum aut grande usque mane.',
        37: 'Diluculo autem cum digessisset vinum Nabal, indicavit ei uxor sua verba haec, et emortuum est cor eius intrinsecus, et factus est quasi lapis.',
        38: 'Cumque pertransissent decem dies, percussit Dominus Nabal, et mortuus est.',
        39: 'Quod cum audisset David mortuum Nabal, ait: Benedictus Dominus, qui iudicavit causam opprobrii mei de manu Nabal, et servum suum custodivit a malo, et malitiam Nabal reddidit Dominus in caput eius. Misit ergo David, et locutus est ad Abigail, ut sumeret eam sibi in uxorem.',
        40: 'Et venerunt pueri David ad Abigail in Carmelum, et locuti sunt ad eam, dicentes: David misit nos ad te, ut accipiat te sibi in uxorem.',
        41: 'Quae consurgens adoravit prona in terram, et ait: Ecce famula tua sit in ancillam, ut lavet pedes servorum domini mei.',
        42: 'Et festinavit, et surrexit Abigail, et ascendit super asinum, et quinque puellae ierunt cum ea, pedissequae eius, et secuta est nuncios David: et facta est illi uxor.',
        43: 'Sed et Achinoam accepit David de Iezrael: et fuit utraque uxor eius.',
        44: 'Saul autem dedit Michol filiam suam uxorem David Phalti, filio Lais, qui erat de Gallim.',
    },
    26: {
        1: 'Et venerunt Ziphaei ad Saul in Gabaa, dicentes: Ecce, David absconditus est in colle Hachila, quae est ex adverso solitudinis.',
        2: 'Et surrexit Saul, et descendit in desertum Ziph, et cum eo tria millia virorum de electis Israel, ut quaereret David in deserto Ziph.',
        3: 'Et castrametatus est Saul in Gabaa Hachila, quae erat ex adverso solitudinis in via: David autem habitabat in deserto. Videns autem quod venisset Saul post se in desertum,',
        4: 'misit exploratores, et didicit quod illuc venisset certissime.',
        5: 'Et surrexit David clam, et venit ad locum ubi erat Saul: cumque vidisset locum, in quo dormiebat Saul, et Abner filius Ner, princeps militiae eius, et Saulem dormientem in tentorio, et reliquum vulgus per circuitum eius,',
        6: 'ait David ad Achimelech Hethaeum, et Abisai filium Sarviae, fratrem Ioab, dicens: Quis descendet mecum ad Saul in castra? Dixitque Abisai: Ego descendam tecum.',
        7: 'Venerunt ergo David, et Abisai ad populum nocte, et invenerunt Saul iacentem et dormientem in tentorio, et hastam fixam in terra ad caput eius: Abner autem et populum dormientes in circuitu eius.',
        8: 'Dixitque Abisai ad David: Conclusit Deus inimicum tuum hodie in manus tuas: nunc ergo perfodiam eum lancea in terra, semel, et secundo opus non erit.',
        9: 'Et dixit David ad Abisai: Ne interficias eum: quis enim extendet manum suam in christum Domini, et innocens erit?',
        10: 'Et dixit David: Vivit Dominus, quia nisi Dominus percusserit eum, aut dies eius venerit ut moriatur, aut in praelium descendens perierit:',
        11: 'propitius sit mihi Dominus ne extendam manum meam in christum Domini. nunc igitur tolle hastam, quae est ad caput eius, et scyphum aquae, et abeamus.',
        12: 'Tulit igitur David hastam, et scyphum aquae, qui erat ad caput Saul, et abierunt: et non erat quisquam, qui videret, et intelligeret, et evigilaret, sed omnes dormiebant, quia sopor Domini irruerat super eos.',
        13: 'Cumque transisset David ex adverso, et stetisset in vertice montis de longe, et esset grande intervallum inter eos,',
        14: 'clamavit David ad populum, et ad Abner filium Ner, dicens: Nonne respondebis, Abner? Et respondens Abner, ait: Quis es tu, qui clamas, et inquietas regem?',
        15: 'Et ait David ad Abner: Numquid non vir tu es? et quis alius similis tui in Israel? quare ergo non custodisti dominum tuum regem? ingressus est enim unus de turba ut interficeret regem, dominum tuum.',
        16: 'Non est bonum hoc, quod fecisti: vivit Dominus, quoniam filii mortis estis vos, qui non custodistis dominum vestrum, christum Domini. nunc ergo vide ubi sit hasta regis, et ubi sit scyphus aquae, qui erat ad caput eius.',
        17: 'Cognovit autem Saul vocem David, et dixit: Numquid vox haec tua, fili mi David? Et ait David: Vox mea, domine mi rex.',
        18: 'Et ait: Quam ob causam dominus meus persequitur servum suum? Quid feci? aut quod est malum in manu mea?',
        19: 'Nunc ergo audi, oro, domine mi rex, verba servi tui: si Dominus incitat te adversum me, odoretur sacrificium: si autem filii hominum, maledicti sunt in conspectu Domini: qui eiecerunt me hodie, ut non habitem in hereditate Domini, dicentes: Vade, servi diis alienis.',
        20: 'Et nunc non effundatur sanguis meus in terram coram Domino: quia egressus est rex Israel ut quaerat pulicem unum, sicut persequitur perdix in montibus.',
        21: 'Et ait Saul: Peccavi, revertere fili mi David: nequaquam enim ultra tibi malefaciam, eo quod pretiosa fuerit anima mea in oculis tuis hodie: apparet enim quod stulte egerim, et ignoraverim multa nimis.',
        22: 'Et respondens David, ait: Ecce hasta regis: transeat unus de pueris regis, et tollat eam.',
        23: 'Dominus autem retribuet unicuique secundum iustitiam suam, et fidem: tradidit enim te Dominus hodie in manum meam, et nolui extendere manum meam in christum Domini.',
        24: 'Et sicut magnificata est anima tua hodie in oculis meis, sic magnificetur anima mea in oculis Domini, et liberet me de omni angustia.',
        25: 'Ait ergo Saul ad David: Benedictus tu fili mi David: et quidem faciens facies, et potens poteris. Abiit autem David in viam suam, et Saul reversus est in locum suum.',
    },
    27: {
        1: 'Et ait David in corde suo: Aliquando incidam una die in manus Saul: nonne melius est ut fugiam, et salver in Terra Philisthinorum, ut desperet Saul, cessetque me quaerere in cunctis finibus Israel? fugiam ergo manus eius.',
        2: 'Et surrexit David, et abiit ipse, et sexcenti viri cum eo, ad Achis filium Maoch regem Geth.',
        3: 'Et habitavit David cum Achis in Geth, ipse et viri eius; et domus eius; et David, et duae uxores eius, Achinoam Iezrahelitis, et Abigail uxor Nabal Carmeli.',
        4: 'Et nunciatum est Sauli quod fugisset David in Geth, et non addidit ultra quaerere eum.',
        5: 'Dixit autem David ad Achis: Si inveni gratiam in oculis tuis, detur mihi locus in una urbium regionis huius, ut habitem ibi: cur enim manet servus tuus in civitate regis tecum?',
        6: 'Dedit itaque ei Achis in die illa Siceleg: propter quam causam facta est Siceleg regum Iuda, usque in diem hanc.',
        7: 'Fuit autem numerus dierum, quibus habitavit David in regione Philisthinorum, quattuor mensium.',
        8: 'Et ascendit David, et viri eius, et agebant praedas de Gessuri, et de Gerzi, et de Amalecitis: hi enim pagi habitabantur in terra antiquitus, euntibus Sur usque ad Terram Aegypti.',
        9: 'Et percutiebat David omnem terram, nec relinquebat viventem virum et mulierem: tollensque oves, et boves, et asinos, et camelos, et vestes, revertebatur, et veniebat ad Achis.',
        10: 'Dicebat autem ei Achis: In quem irruisti hodie? Respondebat David: Contra meridiem Iudae, et contra meridiem Ierameel, et contra meridiem Ceni.',
        11: 'Virum et mulierem non vivificabat David, nec adducebat in Geth, dicens: Ne forte loquantur adversum nos: Haec fecit David: et hoc erat decretum illi omnibus diebus quibus habitavit in regione Philisthinorum.',
        12: 'Credidit ergo Achis David, dicens: Multa mala operatus est contra populum suum Israel: erit igitur mihi servus sempiternus.',
    },
    28: {
        1: 'Factum est autem in diebus illis, congregaverunt Philisthiim agmina sua, ut praepararentur ad bellum contra Israel: dixitque Achis ad David: Sciens nunc scito, quoniam mecum egredieris in castris tu, et viri tui.',
        2: 'Dixitque David ad Achis: Nunc scies quae facturus est servus tuus. Et ait Achis ad David: Et ego custodem capitis mei ponam te cunctis diebus.',
        3: 'Samuel autem mortuus est, planxitque eum omnis Israel, et sepelierunt eum in Ramatha urbe sua. Et Saul abstulit magos, et hariolos de terra. et interfecit eos qui pythones habebant in ventre.',
        4: 'Congregatique sunt Philisthiim, et venerunt, et castrametati sunt in Sunam: congregavit autem et Saul universum Israel, et venit in Gelboe.',
        5: 'Et vidit Saul castra Philisthiim, et timuit, et expavit cor eius nimis.',
        6: 'Consuluitque Dominum, et non respondit ei neque per somnia, neque per sacerdotes, neque per prophetas.',
        7: 'Dixitque Saul servis suis: Quaerite mihi mulierem habentem pythonem, et vadam ad eam, et sciscitabor per illam. Et dixerunt servi eius ad eum: Est mulier pythonem habens in Endor.',
        8: 'Mutavit ergo habitum suum, vestitusque est aliis vestimentis, et abiit ipse, et duo viri cum eo, veneruntque ad mulierem nocte, et ait illi: Divina mihi in pythone, et suscita mihi quem dixero tibi.',
        9: 'Et ait mulier ad eum: Ecce, tu nosti quanta fecerit Saul, et quo modo eraserit magos et hariolos de terra: quare ergo insidiaris animae meae, ut occidar?',
        10: 'Et iuravit ei Saul in Domino, dicens: Vivit Dominus, quia non eveniet tibi quidquam mali propter hanc rem.',
        11: 'Dixitque ei mulier: Quem suscitabo tibi? Qui ait: Samuelem mihi suscita.',
        12: 'Cum autem vidisset mulier Samuelem, exclamavit voce magna, et dixit ad Saul: Quare imposuisti mihi? Tu es enim Saul.',
        13: 'Dixitque ei rex: Noli timere: quid vidisti? Et ait mulier ad Saul: Deos vidi ascendentes de terra.',
        14: 'Dixitque ei: Qualis est forma eius? Quae ait: Vir senex ascendit, et ipse amictus est pallio. Et intellexit Saul quod Samuel esset, et inclinavit se super faciem suam in terra, et adoravit.',
        15: 'Dixit autem Samuel ad Saul: Quare inquietasti me ut suscitarer? Et ait Saul: Coarctor nimis: siquidem Philisthiim pugnant adversum me, et Deus recessit a me, et exaudire me noluit neque in manu prophetarum, neque per somnia: vocavi ergo te, ut ostenderes mihi quid faciam.',
        16: 'Et ait Samuel: Quid interrogas me, cum Dominus recesserit a te, et transierit ad aemulum tuum?',
        17: 'Faciet enim tibi Dominus sicut locutus est in manu mea, et scindet regnum tuum de manu tua, et dabit illud proximo tuo David:',
        18: 'quia non obedisti voci Domini, neque fecisti iram furoris eius in Amalec. idcirco quod pateris, fecit tibi Dominus hodie.',
        19: 'Et dabit Dominus etiam Israel tecum in manus Philisthiim: cras autem tu et filii tui mecum eritis: sed et castra Israel tradet Dominus in manus Philisthiim.',
        20: 'Statimque Saul cecidit porrectus in terram: extimuerat enim verba Samuelis, et robur non erat in eo, quia non comederat panem tota die illa.',
        21: 'Ingressa est itaque mulier illa ad Saul, (conturbatus enim erat valde) dixitque ad eum: Ecce obedivit ancilla tua voci tuae, et posui animam meam in manu tua: et audivi sermones tuos, quos locutus es ad me.',
        22: 'Nunc igitur audi et tu vocem ancillae tuae, et ponam coram te buccellam panis, ut comedens convalescas, et possis iter agere.',
        23: 'Qui renuit, et ait: Non comedam. Coegerunt autem eum servi sui et mulier, et tandem audita voce eorum surrexit de terra, et sedit super lectum.',
        24: 'Mulier autem illa habebat vitulum pascualem in domo, et festinavit, et occidit eum: tollensque farinam, miscuit eam, et coxit azyma,',
        25: 'et posuit ante Saul et ante servos eius. Qui cum comedissent, surrexerunt, et ambulaverunt per totam noctem illam.',
    },
    29: {
        1: 'Congregata sunt ergo Philisthiim universa agmina in Aphec: sed et Israel castrametatus est super fontem, qui erat in Iezrahel.',
        2: 'Et satrapae quidem Philisthiim incedebant in centuriis et millibus: David autem et viri eius erant in novissimo agmine cum Achis.',
        3: 'Dixeruntque principes Philisthiim ad Achis: Quid sibi volunt Hebraei isti? Et ait Achis ad principes Philisthiim: Num ignoratis David, qui fuit servus Saul regis Israel, et est apud me multis diebus, vel annis, et non inveni in eo quidquam ex die qua transfugit ad me, usque ad diem hanc?',
        4: 'Irati sunt autem adversus eum principes Philisthiim, et dixerunt ei: Revertatur vir iste, et sedeat in loco suo, in quo constituisti eum, et non descendat nobiscum in praelium, ne fiat nobis adversarius, cum praeliari coeperimus: quomodo enim aliter poterit placare dominum suum, nisi in capitibus nostris?',
        5: 'Nonne iste est David, cui cantabant in choris, dicentes: Percussit Saul in millibus suis, et David in decem millibus suis?',
        6: 'Vocavit ergo Achis David, et ait ei: Vivit Dominus, quia rectus es tu, et bonus in conspectu meo: et exitus tuus, et introitus tuus mecum est in castris: et non inveni in te quidquam mali ex die qua venisti ad me, usque in diem hanc: sed satrapis non places.',
        7: 'Revertere ergo, et vade in pace, et non offendas oculos satraparum Philisthiim.',
        8: 'Dixitque David ad Achis: Quid enim feci, et quid invenisti in me servo tuo a die qua fui in conspectu tuo usque in diem hanc, ut non veniam, et pugnem contra inimicos domini mei regis?',
        9: 'Respondens autem Achis, locutus est ad David: Scio quia bonus es tu in oculis meis, sicut Angelus Dei: sed principes Philisthinorum dixerunt: Non ascendet nobiscum in praelium.',
        10: 'Igitur consurge mane tu, et servi domini tui, qui venerunt tecum: et cum de nocte surrexeritis, et coeperit dilucescere, pergite.',
        11: 'Surrexit itaque de nocte David ipse et viri eius, ut proficiscerentur mane, et reverterentur ad Terram Philisthiim: Philisthiim autem ascenderunt in Iezrahel.',
    },
    30: {
        1: 'Cumque venissent David et viri eius in Siceleg die tertia, Amalecitae impetum fecerant ex parte australi in Siceleg, et percusserant Siceleg, et succenderant eam igni.',
        2: 'Et captivas duxerant mulieres ex ea, a minimo usque ad magnum: et non interfecerant quemquam, sed secum duxerant, et pergebant itinere suo.',
        3: 'Cum ergo venissent David et viri eius ad civitatem, et invenissent eam succensam igni, et uxores suas, et filios suos, et filias ductas esse captivas,',
        4: 'levaverunt David et populus qui erat cum eo voces suas, et planxerunt donec deficerent in eis lacrymae.',
        5: 'Siquidem et duae uxores David captivae ductae fuerant, Achinoam Iezrahelites, et Abigail uxor Nabal Carmeli.',
        6: 'Et contristatus est David valde: volebat enim eum populus lapidare, quia amara erat anima uniuscuiusque viri super filiis suis et filiabus: confortatus est autem David in Domino Deo suo.',
        7: 'Et ait ad Abiathar sacerdotem filium Achimelech: Applica ad me ephod. Et applicavit Abiathar ephod ad David,',
        8: 'et consuluit David Dominum, dicens: Persequar latrunculos hos, et comprehendam eos, an non? Dixitque ei Dominus: Persequere: absque dubio enim comprehendes eos, et excuties praedam.',
        9: 'Abiit ergo David ipse, et sexcenti viri qui erant cum eo, et venerunt usque ad Torrentem Besor: et lassi quidam substiterunt.',
        10: 'Persecutus est autem David ipse, et quadringenti viri: substiterant enim ducenti, qui lassi transire non poterant Torrentem Besor.',
        11: 'Et invenerunt virum Aegyptium in agro, et adduxerunt eum ad David: dederuntque ei panem ut comederet, et biberet aquam,',
        12: 'sed et fragmen massae caricarum, et duas ligaturas uvae passae. Quae cum comedisset, reversus est spiritus eius, et refocillatus est: non enim comederat panem, neque biberat aquam, tribus diebus et tribus noctibus.',
        13: 'Dixit itaque ei David: Cuius es tu? vel unde? et quo pergis? Qui ait: Puer Aegyptius ego sum, servus viri Amalecitae: dereliquit autem me dominus meus, quia aegrotare coepi nudiustertius.',
        14: 'Siquidem nos erupimus ad australem plagam Cerethi, et contra Iudam, et ad meridiem Caleb, et Siceleg succendimus igni.',
        15: 'Dixitque ei David: Potes me ducere ad cuneum istum? Qui ait: Iura mihi per Deum, quod non occidas me, et non tradas me in manus domini mei, et ego ducam te ad cuneum istum. Et iuravit ei David.',
        16: 'Qui cum duxisset eum, ecce illi discumbebant super faciem universae terrae comedentes et bibentes, et quasi festum celebrantes diem, pro cuncta praeda, et spoliis quae ceperant de Terra Philisthiim, et de Terra Iuda.',
        17: 'Et percussit eos David a vespere usque ad vesperam alterius diei, et non evasit ex eis quisquam, nisi quadringenti viri adolescentes, qui ascenderant camelos, et fugerant.',
        18: 'Eruit ergo David omnia, quae tulerant Amalecitae, et duas uxores suas eruit.',
        19: 'Nec defuit quisquam a parvo usque ad magnum, tam de filiis quam de filiabus, et de spoliis, et quaecumque rapuerant, omnia reduxit David.',
        20: 'Et tulit universos greges et armenta, et minavit ante faciem suam: dixeruntque: Haec est praeda David.',
        21: 'Venit autem David ad ducentos viros, qui lassi substiterant, nec sequi potuerant David, et residere eos iusserat in Torrente Besor: qui egressi sunt obviam David, et populo qui erat cum eo. Accedens autem David ad populum, salutavit eos pacifice.',
        22: 'Respondensque omnis vir pessimus, et iniquus de viris, qui ierant cum David, dixit: Quia non venerunt nobiscum, non dabimus eis quidquam de praeda, quam eruimus: sed sufficiat unicuique uxor sua et filii: quos cum acceperint, recedant.',
        23: 'Dixit autem David: Non sic facietis fratres mei de his, quae tradidit nobis Dominus, et custodivit nos, et dedit latrunculos, qui eruperant adversum nos, in manus nostras:',
        24: 'nec audiet vos quisquam super sermone hoc. aequa enim pars erit descendentis ad praelium, et remanentis ad sarcinas, et similiter divident.',
        25: 'Et factum est hoc ex die illa, et deinceps constitutum et praefinitum, et quasi lex in Israel usque in diem hanc.',
        26: 'Venit ergo David in Siceleg, et misit dona de praeda senioribus Iuda proximis suis, dicens: Accipite benedictionem de praeda hostium Domini:',
        27: 'His, qui erant in Bethel, et qui in Ramoth ad Meridiem, et qui in Geter,',
        28: 'et qui in Aroer, et qui in Sephamoth, et qui in Esthamo,',
        29: 'et qui in Rachal, et qui in urbibus Ierameel, et qui in urbibus Ceni,',
        30: 'et qui in Harama, et qui in lacu Asan, et qui in Athach,',
        31: 'et qui in Hebron, et reliquis qui erant in his locis, in quibus commoratus fuerat David ipse, et viri eius.',
    },
    31: {
        1: 'Philisthiim autem pugnabant adversum Israel: et fugerunt viri Israel ante faciem Philisthiim, et ceciderunt interfecti in monte Gelboe.',
        2: 'Irrueruntque Philisthiim in Saul, et in filios eius, et percusserunt Ionathan, et Abinadab, et Melchisua filios Saul,',
        3: 'totumque pondus praelii versum est in Saul: et consecuti sunt eum viri sagittarii, et vulneratus est vehementer a sagittariis.',
        4: 'Dixitque Saul ad armigerum suum: Evagina gladium tuum, et percute me: ne forte veniant incircumcisi isti, et interficiant me, illudentes mihi. Et noluit armiger eius: fuerat enim nimio terrore perterritus. arripuit itaque Saul gladium suum, et irruit super eum.',
        5: 'Quod cum vidisset armiger eius, videlicet quod mortuus esset Saul, irruit etiam ipse super gladium suum, et mortuus est cum eo.',
        6: 'Mortuus est ergo Saul, et tres filii eius, et armiger illius, et universi viri eius in die illa pariter.',
        7: 'Videntes autem filii Israel, qui erant trans vallem, et trans Iordanem, quod fugissent viri Israelitae, et quod mortuus esset Saul, et filii eius, reliquerunt civitates suas, et fugerunt: veneruntque Philisthiim, et habitaverunt ibi.',
        8: 'Facta autem die altera, venerunt Philisthiim, ut spoliarent interfectos, et invenerunt Saul et tres filios eius iacentes in monte Gelboe.',
        9: 'Et praeciderunt caput Saul, et spoliaverunt eum armis: et miserunt in Terram Philisthinorum per circuitum, ut annunciaretur in templo idolorum, et in populis.',
        10: 'Et posuerunt arma eius in templo Astaroth, corpus vero eius suspenderunt in muro Bethsan.',
        11: 'Quod cum audissent habitatores Iabes Galaad, quaecumque fecerant Philisthiim Saul,',
        12: 'surrexerunt omnes viri fortissimi, et ambulaverunt tota nocte, et tulerunt cadaver Saul, et cadavera filiorum eius de muro Bethsan: veneruntque Iabes Galaad, et combusserunt ea ibi igni:',
        13: 'et tulerunt ossa eorum, et sepelierunt in nemore Iabes, et ieiunaverunt septem diebus.',
    },
}
